const qS=id=>S.q[id]&&!S.q[id].done?S.q[id].s:(S.q[id]&&S.q[id].done?'done':null);
/* kampania: zadania Aktu I po kolei; finał otwiera się po ukończeniu 3 z 4 */
const CAMPAIGN={n:'Akt I: Szepty Velesii',q:['osadnicy','niepamiec','kurhan','dlug'],fin:'czarnybor'};
const campDone=()=>CAMPAIGN.q.filter(id=>qS(id)==='done').length;
const campFinOk=()=>campDone()>=3;
/* miejsca wypraw z zadań: kiedy można tam wyruszyć (zadanie q na etapie s), kraina wrogów r, poziom L */
const QSITE={
 polana:{q:'osadnicy',s:'pieczec',r:2,L:3,st:()=>Math.max(9,S.stage),lv:'5+',idle:'Pieczęć milczy. Na razie nie ma tu czego szukać.',end:'Mgła rzednie. W samym środku kręgu kamieni czeka pieczęć…',go:'Podejdź do pieczęci'},
 kurhan:{q:'kurhan',s:'kurhan',r:2,L:2,st:()=>Math.max(6,S.stage),lv:'4+',idle:'Kurhan milczy. Na polu została tylko bruzda po pługu.',end:'W komorze grobowej, na kamiennym tronie, siedzi wódz w zardzewiałej zbroi. Jego oczy płoną bladym światłem…',go:'Stań przed wodzem'},
 czarnybor:{q:'czarnybor',s:'bor',r:0,L:4,boss:'troll',st:()=>Math.max(10,S.stage)+(S.fl.osa==='broken'?1:0)+(S.fl.kur==='relikwia'?1:0),
  pool:[[0,'wilk'],[0,'borowy'],[0,'kultysta'],[1,'dzik'],[1,'pajak'],[2,'kultysta'],[3,'wilkolak']],lv:'6+',idle:'Czarny Bór szumi złowrogo. Na razie lepiej tam nie chodzić.',end:'Troll wali się na ziemię jak ścięty dąb. Spomiędzy drzew wychodzi ktoś w czarnym płaszczu…',go:'Kto tam?'}};
const qsiteOpen=k=>{const Q=QSITE[k];return !!Q&&qS(Q.q)===Q.s};
const DLG={
 /* --- Znikający osadnicy --- */
 osa_start:{p:'wlodar',who:'Pan Dobiesław, włodarz Dąbrowy',t:'Dobrze, że jesteście. Od miesiąca nocą puszcza szepcze – ludzie słyszą w liściach własne imiona. Zwierzęta uciekają z lasu na nasze pastwiska, a trzech drwali poszło na wyrąb i nie wróciło. Ani śladu walki.\nTo bandyci z traktu, mówię wam. Porywają ludzi i sprzedają za Grzbiet. A ta stara wiedźma Wila opowiada bajki o pieczęciach…',
  o:[{t:'Zajmiemy się tym.',fx:()=>{qSet('osadnicy','rozmowa');return {txt:'Włodarz kiwa głową. „Porozmawiajcie z kim chcecie, byle szybko.”'}}},{t:'Może później.'}]},
 osa_wl2:{p:'wlodar',who:'Pan Dobiesław, włodarz Dąbrowy',t:'No i co? Ruszacie na tych zbójów? Zapłacę uczciwie – i dwór w Weleszowie się o tym dowie.',
  o:[{t:'Ruszamy na Trakt Bandytów.',fx:()=>{qSet('osadnicy','bandyci');rep('dwor',3)}},{t:'Jeszcze się rozejrzymy.'}]},
 osa_wl_idle:{p:'wlodar',who:'Pan Dobiesław, włodarz Dąbrowy',t:()=>qS('osadnicy')==='done'?(S.fl.osa==='band'?'Spokój w puszczy… prawie. Ale ludzie wciąż czasem nie wracają.':'Wila mówi, że las ucichł. Nie rozumiem tego, ale ludzie przestali znikać – dziękuję.'):'Czekam na wieści.',o:[{t:'Bywaj.'}]},
 osa_wila:{p:'szeptucha',who:'Wila, szeptucha',t:'Bandyci? Bandyci nie szepczą imion o północy i nie zostawiają szronu na liściach w środku lata.\nPod puszczą coś się budzi. Na Mglistej Polanie stoi krąg i pieczęć z czasów Asterionu – czuję, że pęka. Ale nie wierzcie mi na słowo: idźcie na stary wyrąb, skąd zniknęli drwale. Sami zobaczycie.',
  o:[{t:'Pójdziemy na wyrąb.',fx:()=>{S.found.wyrab=1;routeFix();unlockLore('asterion');qSet('osadnicy','slady');rep('duchy',5);return {txt:'Wila kreśli patykiem drogę przez puszczę. „Ja pójdę na polanę i spróbuję utrzymać pieczęć. Spieszcie się.” Opuszczony wyrąb pojawia się na mapie. (Nowy wpis w kronice: Pieczęcie Asterionu)'}}},
   {t:'Włodarz ma rację – to bandyci.',fx:()=>{qSet('osadnicy','bandyci');rep('duchy',-5);rep('dwor',3);return {txt:'Wila wzrusza ramionami. „Idźcie. Las i tak dalej będzie wołał.”'}}},{t:'Musimy to przemyśleć.'}]},
 osa_wyrab:{p:'leszy',who:'Opuszczony wyrąb',t:'Siekiery wciąż tkwią w pniach, a przy wygasłym ognisku stoją trzy pary butów – równo, jakby ktoś zdjął je przed snem. Bose ślady prowadzą w głąb puszczy, na północ. Na korze najbliższego dębu ktoś wydrapał paznokciami jedno słowo: „WOŁA”.\nZ lasu dochodzi szept. Słyszycie w nim własne imiona.',
  o:[{t:'Idźcie bosym tropem',fx:()=>{S.found.polana=1;routeFix();qSet('osadnicy','pieczec');return {txt:'Ślady prowadzą przez gąszcz aż do ściany mgły. Za nią majaczą kamienie kręgu – Mglista Polana. (Odkryta na mapie)'}}},
   {c:['lucznik','druid','lotr'],t:'Odczytaj ślady dokładnie',fx:()=>{S.found.polana=1;routeFix();qSet('osadnicy','pieczec');partyHeroes().forEach(h=>gainXp(h,25+S.stage*5));return {txt:'Drwale szli spokojnie, jak we śnie. Obok ich śladów biegną inne – za długie na wilka, za lekkie na człowieka. Coś ich prowadziło. Teraz wiecie, czego się spodziewać. (Doświadczenie dla drużyny, Mglista Polana na mapie)'}}},
   {t:'Zatkajcie uszy i wróćcie później.'}]},
 osa_wila_idle:{p:'szeptucha',who:'Wila, szeptucha',t:()=>S.fl.osa==='restored'?'Pieczęć śpiewa znowu cicho. Dobrze się spisaliście.':S.fl.osa==='broken'?'Rozbiliście pieczęć dla garści kryształów. Las to zapamięta.':S.fl.osa==='band'?'Rozbiliście bandę, a las dalej woła. Mówiłam.':'Zioła, odczynianie, obrzędy – po to tu przychodzicie, prawda? Moja chata stoi przy dębie.',o:[{t:'Bywaj, Wilo.'}]},
 osa_band_end:{p:'wlodar',who:'Pan Dobiesław, włodarz Dąbrowy',t:'Herszt rozbity, trakt wolny! Wiedziałem. Oto obiecana zapłata – dwór w Weleszowie usłyszy o waszej dzielności.\n(Gdzieś w puszczy, wbrew wszystkiemu, znów ktoś nie wrócił do domu…)',
  o:[{t:'Bierzemy zapłatę.',fx:()=>{const t=reward(150,1,dworMul());rep('dwor',12);rep('duchy',-5);S.fl.osa='band';qEnd('osadnicy','Rozbiliście bandytów dla włodarza. Dwór jest zadowolony, ale pieczęć w puszczy wciąż jest pęknięta. '+t);return {txt:'Nagroda: '+t+'. +Dwór'}}},
   {t:'Oddaj nagrodę rodzinom zaginionych.',fx:()=>{rep('lud',15);rep('dwor',6);S.fl.osa='band';qEnd('osadnicy','Rozbiliście bandytów, a nagrodę oddaliście rodzinom zaginionych. Lud tego nie zapomni.');return {txt:'Wdowy i matki z Dąbrowy płaczą i błogosławią kompanię. +Lud, +Dwór'}}}]},
 osa_seal:{p:'duch',who:'Pieczęć Asterionu',t:'Na środku polany, w kręgu runicznych kamieni, klęczy Wila. Trzyma dłonie na pękniętej pieczęci i szepcze bez przerwy, a spod jej palców sączy się zimne światło. Widać w nim blade twarze zaginionych drwali, uwięzione jak ryby pod lodem. To od nich płyną szepty.\n„Pomóżcie mi ją zamknąć” – charczy Wila. – „Albo rozbijcie… ale wtedy nie wiem, co wyjdzie z ziemi.” Kryształy w pęknięciu warte są fortunę.',
  o:[{t:'Odnówcie pieczęć według wskazówek Wili.',fx:()=>{rep('duchy',15);rep('lud',8);S.fl.osa='restored';qSet('osadnicy','piecz_wroc');return {txt:'Kamienie budzą się z cichym śpiewem. Światło gaśnie, a we mgle słychać kroki – zaginieni wracają do domu, oszołomieni, ale żywi. +Duchy, +Lud'}}},
   {c:['druid','kaplan'],t:'Wzmocnij pieczęć własną mocą',fx:()=>{rep('duchy',25);rep('lud',8);S.mat.esc+=3;S.fl.osa='restored';qSet('osadnicy','piecz_wroc');return {txt:'Twoja moc splata się z runami. Pieczęć jest teraz silniejsza niż kiedykolwiek, a w szczelinie zostają trzy krople czystej esencji. Zaginieni wracają. +Duchy (dużo), +Lud, +3 esencje'}}},
   {t:'Rozbijcie pieczęć i zabierzcie kryształy.',fx:()=>{const t=reward(260,2);rep('duchy',-30);rep('lud',-10);S.fl.osa='broken';qSet('osadnicy','piecz_wroc');return {txt:'Kamień pęka z hukiem. Twarze w świetle krzyczą bezgłośnie i znikają, a fala zimnej mocy przetacza się przez puszczę i ginie gdzieś na zachodzie. Szepty milkną… zbyt nagle. '+t+'. −Duchy, −Lud (Ta decyzja będzie miała konsekwencje.)'}}}]},
 osa_seal_end:{p:'szeptucha',who:'Wila, szeptucha',t:()=>S.fl.osa==='broken'?'Czuję to w kościach. Pieczęci już nie ma. To, co spało pod polaną, popłynęło na zachód, w Czarny Bór. Coś obudziliście – i to wy będziecie musieli to potem uśpić.':'Słyszę, jak kamienie śpiewają! Ludzie wracają z lasu. Takiej kompanii Velesia dawno nie widziała.\nStara jestem, ale nogi jeszcze niosą. Jeśli chcecie, pójdę z wami – ktoś musi wam opatrywać rany i gadać z duchami.',
  o:[{t:'Wilo, chodź z nami!',when:()=>S.fl.osa==='restored',fx:()=>{const r=addUniq('szeptunka');qEnd('osadnicy','Odnowiliście pieczęć Asterionu na Mglistej Polanie. Zaginieni wrócili, a szeptucha Wila dołączyła do kompanii. Pierwszy ślad Asterionu…');unlockLore('asterion');return {txt:r+' (Unikalna towarzyszka: druidka z ludową magią – leczenie i odporność na mrok dla drużyny.)'}}},
   {t:'Zostań w Dąbrowie, będziemy cię odwiedzać.',when:()=>S.fl.osa==='restored',fx:()=>{const t=reward(80,null);qEnd('osadnicy','Odnowiliście pieczęć Asterionu. Zaginieni wrócili do domów. '+t);S.fl.wila=1;return {txt:'Wila wciska wam sakiewkę od wdzięcznych rodzin: '+t+'. (Możesz ją jeszcze zaprosić do kompanii w Dąbrowie.)'}}},
   {t:'Przykro nam.',when:()=>S.fl.osa==='broken',fx:()=>{qEnd('osadnicy','Rozbiliście pieczęć Asterionu dla kryształów. Zaginieni przepadli, a duchy puszczy są niespokojne.');return {txt:'Wila odwraca się plecami.'}}}]},
 wila_join:{p:'szeptucha',who:'Wila, szeptucha',t:'Wróciliście. Zaproszenie dalej aktualne?',o:[{t:'Chodź z nami.',fx:()=>{const r=addUniq('szeptunka');if(S.roster.some(h=>h.uniq==='szeptunka'))S.fl.wila=0;return {txt:r}}},{t:'Jeszcze nie.'}]},
 /* --- Bestia z puszczy --- */
 bes_start:{p:'lowczyni',who:'Bogna, łowczyni z Kręgoszewa',t:'Coś zabija bydło pod grodem. Nie wilki – wilki same uciekają z puszczy na nasze pastwiska, a za nimi idzie coś cięższego. Ślady jak tarcza.\nPomożecie? Najpierw przetrzebcie wilki, bo zagryzą pół wsi, zanim w ogóle dojdziemy do bestii.',
  o:[{t:'Zapolujemy.',fx:()=>{qSet('bestia','wilki');rep('lud',3)}},{t:'Nie teraz.'}]},
 bes_plan:{p:'lowczyni',who:'Bogna, łowczyni z Kręgoszewa',t:'Wilki przetrzebione. Tropy prowadzą do jaru pod starym bukiem – tam bestia ma legowisko. Ogromne, czarne, z porożem jak korona. Jak ją bierzemy?',
  o:[{t:'Prosto w legowisko!',fx:()=>{closeModal();roadFight(['troll','wilk','wilk'],'Legowisko bestii',{qd:'bes_win',st:Math.max(4,S.stage)});return {fight:1}}},
   {c:['lucznik','lotr'],t:'Zastawimy pułapkę na jej ścieżce',fx:()=>{closeModal();roadFight(['troll','wilk'],'Pułapka na bestię',{qd:'bes_win',st:Math.max(3,S.stage-1)});S.fl.trap=1;return {fight:1}}},
   {c:['druid'],t:'To nie potwór – to strażnik lasu. Pozwól mi z nim pomówić',go:'bes_druid'},{t:'Musimy się przygotować.'}]},
 bes_druid:{p:'bestia',who:'Strażnik puszczy',t:'W jarze czeka nie bestia, lecz leszy – stary strażnik lasu, wściekły i zraniony. W jego boku tkwi grot z velesiańskim herbem. Ktoś polował tu, gdzie polować nie wolno.\nDruid w kompanii mówi do niego mową liści. Leszy słucha.',
  o:[{t:'Obiecaj, że ludzie nie będą polować w jego jarze',fx:()=>{const t=reward(80,null);rep('duchy',15);rep('lud',4);qEnd('bestia','Druid uspokoił leszego – strażnika puszczy. Bydło jest bezpieczne, a w jarze pod bukiem nikt już nie poluje. '+t);return {txt:'Leszy wyrywa grot i znika między drzewami. Bogna kręci głową z niedowierzaniem, ale płaci: '+t+'. +Duchy'}}},
   {t:'Zbyt ryzykowne – walczymy',fx:()=>{closeModal();roadFight(['troll','wilk','wilk'],'Legowisko bestii',{qd:'bes_win',st:Math.max(4,S.stage)});return {fight:1}}}]},
 bes_win:{p:'lowczyni',who:'Bogna, łowczyni z Kręgoszewa',t:()=>`Bestia leży! ${S.fl.trap?'Pułapka zadziałała jak marzenie. ':''}Gród wam tego nie zapomni. Łeb zawiesimy nad bramą.`,
  o:[{t:'Przyjmij nagrodę',fx:()=>{const t=reward(S.fl.trap?190:160,1);rep('lud',12);S.tro.troll=(S.tro.troll||0)+1;qEnd('bestia','Ubiliście bestię z puszczy. Kręgoszew wiwatuje. '+t+', trofeum bestii.');return {txt:'Nagroda: '+t+' i trofeum bestii (sprzedasz w Gildii łowców). +Lud'}}}]},
 bes_idle:{p:'lowczyni',who:'Bogna, łowczyni z Kręgoszewa',t:()=>qS('bestia')==='done'?'Dobrze się z wami poluje.':'Wilki, wilki, wilki. Ile już ubiliście?',o:[{t:'Bywaj.'}]},
 /* --- Spór o artefakt --- */
 art_j:{p:'szlachcianka',who:'Pani Jadwiga z rodu Jastrzębców',t:'Róg Welesa – relikwia z kurhanów – należy się mojemu rodowi. Mam pergamin z pieczęcią mojego pradziada! A Gryfici chcą go tylko po to, by wkupić się w łaski króla.\nPomóżcie mi, a Jastrzębcy będą waszymi przyjaciółmi na dworze.',
  o:[{t:'Stajemy po stronie Jastrzębców.',fx:()=>{qSet('artefakt','rog_j');rep('dwor',3);return {txt:'„Wiedziałam, że rozpoznacie słuszną sprawę.” Róg spoczywa podobno w Kurhanach Przodków.'}}},
   {t:'Skąd właściwie ten róg się wziął?',fx:()=>{qSet('artefakt','sledztwo');return {txt:'Jadwiga marszczy brwi. „Z kurhanów, rzecz jasna. Ale… pergamin przyniósł nam pewien uczony, Mściwój.” Warto zapytać starszego w Kurhanowie.'}}},{t:'Wysłucham jeszcze drugiej strony.'}]},
 art_b:{p:'magnat',who:'Pan Bogusz z rodu Gryfitów',t:'Jastrzębcy? Złodzieje i fałszerze! Róg Welesa należy do Gryfitów – mam akt nadania od samego króla Welimira. Pewien uczony człek, Mściwój, odnalazł go w archiwach.\nPrzynieście mi róg, a sowicie zapłacę.',
  o:[{t:'Stajemy po stronie Gryfitów.',fx:()=>{qSet('artefakt','rog_b');rep('dwor',3);return {txt:'„Mądry wybór.” Róg spoczywa podobno w Kurhanach Przodków.'}}},
   {t:'Ten sam Mściwój pomógł Jastrzębcom… Sprawdzimy to.',fx:()=>{qSet('artefakt','sledztwo');return {txt:'Bogusz czerwienieje. „Co takiego?!” – Najlepiej zapytać starszego w Kurhanowie, skąd róg trafił do mogił.'}}},{t:'Wysłucham jeszcze drugiej strony.'}]},
 art_idle_j:{p:'szlachcianka',who:'Pani Jadwiga z rodu Jastrzębców',t:()=>S.fl.art==='j'?'Róg zdobi naszą kaplicę. Jastrzębcy pamiętają o przyjaciołach.':S.fl.art==='b'?'Zdrajcy. Nie mamy o czym rozmawiać.':S.fl.art==='prawda'?'Mściwój… omal nie wywołał wojny rodów. Dziękuję, że przejrzeliście go na wylot.':'Czekam na róg.',o:[{t:'Bywaj, pani.'}]},
 art_idle_b:{p:'magnat',who:'Pan Bogusz z rodu Gryfitów',t:()=>S.fl.art==='b'?'Róg Welesa w rękach Gryfitów! Król już o tym wie.':S.fl.art==='j'?'Jastrzębcy dostali róg… zapamiętam to sobie.':S.fl.art==='prawda'?'Dałem się nabrać jak żak. Dobrze, że ktoś trzeźwo myślał.':'No i gdzie ten róg?',o:[{t:'Bywaj, panie.'}]},
 art_odd_j:{p:'szlachcianka',who:'Pani Jadwiga z rodu Jastrzębców',t:'Róg Welesa! Jest piękniejszy, niż mówiły kroniki. Gryfici dostaną szału.',
  o:[{t:'Oddaj róg',fx:()=>{const t=reward(220,1,dworMul());rep('dwor',12);rep('duchy',-10);S.fl.art='j';qEnd('artefakt','Oddaliście Róg Welesa Jastrzębcom. Gryfici są wściekli, a mieszkańcy Kurhanowa szepczą o zbezczeszczonym grobie. '+t);return {txt:'Nagroda: '+t+'. +Dwór, −Duchy'}}}]},
 art_odd_b:{p:'magnat',who:'Pan Bogusz z rodu Gryfitów',t:'A więc jest! Róg Welesa w rękach Gryfitów – tak jak być powinno.',
  o:[{t:'Oddaj róg',fx:()=>{const t=reward(220,1,dworMul());rep('dwor',12);rep('duchy',-10);S.fl.art='b';qEnd('artefakt','Oddaliście Róg Welesa Gryfitom. Jastrzębcy przysięgają zemstę, a duchy kurhanów są niespokojne. '+t);return {txt:'Nagroda: '+t+'. +Dwór, −Duchy'}}}]},
 art_starszy:{p:'starszy',who:'Radogost, starszy Kurhanowa',t:'Róg Welesa? Leżał w kurhanie Welimira od tysiąca lat – aż pół roku temu przyszedł tu „uczony” z Weleszowa. Mściwój. Wypytywał, mierzył, rysował… a potem kurhan był rozkopany, a róg zniknął.\nŻaden ród nie ma do niego prawa. To dar dla przodków.',
  o:[{t:'Mściwój sfałszował dowody dla obu rodów!',fx:()=>{qSet('artefakt','demask');unlockLore('kurhany');rep('duchy',5);return {txt:'Starszy kiwa głową. „Znajdźcie go w Weleszowie. I przywieźcie róg z powrotem do przodków.”'}}},
   {c:['lotr','bard'],t:'Popytajcie kramarzy, komu sprzedawał pergaminy',fx:()=>{S.fl.proof=1;qSet('artefakt','demask');unlockLore('kurhany');rep('duchy',5);return {txt:'Kramarz w Sanowie pamięta Mściwoja – kupił dwa czyste pergaminy i lak dwóch różnych rodów. Macie dowód nie do podważenia.'}}}]},
 art_spy:{p:'szpieg',who:'Mściwój, „uczony”',t:()=>`Ach, kompania! Słyszałem, że węszycie. ${S.fl.proof?'Pergaminy z Sanowa, mówicie? Hm. ':''}Posłuchajcie: dwa rody płacą mi za „dowody”, a ja płacę wam za milczenie. Trzysta złotych. Wszyscy zadowoleni.\nRóg i tak siedzi bezpiecznie w mojej skrytce.`,
  o:[{t:'Wydajmy go królewskiemu sądowi',fx:()=>{const t=reward(S.fl.proof?220:160,1,dworMul());rep('dwor',18);rep('duchy',15);rep('lud',6);S.fl.art='prawda';qEnd('artefakt','Zdemaskowaliście Mściwoja. Oba rody pogodziły się (na chwilę), a Róg Welesa wrócił do kurhanu przodków. '+t);return {txt:'Straż zabiera Mściwoja. Jastrzębcy i Gryfici razem płacą wam nagrodę: '+t+'. Róg wraca do Kurhanowa. +Dwór, +Duchy, +Lud'}}},
   {c:['lotr'],t:'Najpierw opróżnij jego skrytkę, potem go wydaj',fx:()=>{const t=reward(320,2);rep('dwor',12);rep('duchy',10);S.fl.art='prawda';qEnd('artefakt','Zdemaskowaliście Mściwoja – po drodze opróżniając jego skrytkę. Róg wrócił do kurhanu. '+t);return {txt:'Kto okrada złodzieja… '+t+'. +Dwór, +Duchy'}}},
   {t:'Bierzemy złoto i milczymy',fx:()=>{S.gold+=300;rep('dwor',-15);rep('duchy',-15);S.fl.art='mil';qEnd('artefakt','Wzięliście łapówkę od Mściwoja. Rody dalej skaczą sobie do gardeł, a róg przepadł. +300 zł');return {txt:'+300 zł. Gdzieś w Kurhanowie stary Radogost długo patrzy w stronę stolicy. −Dwór, −Duchy'}}}]},
 /* --- Skrzydlaci --- */
 skr_start:{p:'husarz',who:'Rotmistrz Zawisza Skrzydlaty',t:'Chcecie jednego z moich w kompanii? Skrzydlatych się nie wynajmuje. Skrzydlatym się zostaje – albo zasługuje na ich przyjaźń.\nDowiedźcie męstwa: przejdźcie wyprawę na trzecim poziomie albo położcie bossa. Potem pogadamy.',
  o:[{t:'Przyjmujemy wyzwanie.',fx:()=>{qSet('skrzydlaci','proba');unlockLore('skrzydlaci')}},{t:'Innym razem.'}]},
 skr_idle:{p:'husarz',who:'Rotmistrz Zawisza Skrzydlaty',t:()=>qS('skrzydlaci')==='done'?'Jaromir pisze, że dobrze mu z wami. Pilnujcie go – i on was upilnuje.':'Słowo się rzekło. Czekam na wieść o waszym męstwie.',o:[{t:'Bywaj, rotmistrzu.'}]},
 skr_patent:{p:'kaplan',who:'Ojciec Światosław, kanclerz',t:()=>S.rep.dwor>=0?'Rotmistrz Zawisza pisał do mnie o was. Dwór dobrze o was mówi – list żelazny wystawię od ręki.':'Rotmistrz pisał o was… ale na dworze krążą o waszej kompanii niepochlebne słowa. List mogę wystawić, lecz kancelaria pobiera opłatę – 200 złotych.',
  o:[{t:'Dziękujemy, ojcze.',when:()=>S.rep.dwor>=0,fx:()=>{qSet('skrzydlaci','przysiega');rep('dwor',4)}},{t:'Zapłać 200 zł',when:()=>S.rep.dwor<0,req:()=>S.gold>=200,rq:'za mało złota',fx:()=>{S.gold-=200;qSet('skrzydlaci','przysiega')}},{t:'Wrócimy później.'}]},
 skr_oath:{p:'husarz',who:'Rotmistrz Zawisza Skrzydlaty',t:'List z kancelarii, wieść o waszym męstwie… Niech będzie. Jaromirze! Wystąp.\nTo najmłodszy z mojej chorągwi – i najdzielniejszy. Pójdzie z wami, jeśli przysięgniecie, że kompania będzie bronić Velesii, gdy przyjdzie potrzeba.',
  o:[{t:'Przysięgamy bronić Velesii.',fx:()=>{const r=addUniq('husarz');if(!S.roster.some(h=>h.uniq==='husarz'))return {txt:r};rep('dwor',10);qEnd('skrzydlaci','Złożyliście przysięgę przed rotmistrzem Zawiszą. Jaromir Skrzydlaty jedzie z kompanią.');return {txt:r+' (Unikalny towarzysz: husarz – paladyn z szablą; w drużynie dodaje +6% ataku i +4% kryt. na wyprawach.)'}}},{t:'Jeszcze nie jesteśmy gotowi.'}]},
 /* --- postacie poboczne --- */
 kasztelan:{p:'kasztelan',who:'Kasztelan Borzywoj',t:()=>'Kręgoszew to brama Velesii od zachodu. Z puszczy i bagien co rusz coś próbuje się przez nią przecisnąć: zbóje z traktu, upiory, ostatnio nawet orkowie zapędzeni aż z Grzbietu.\nKontrakty na zagrożenia graniczne wisią w komendanturze. Płacę rzetelnie.'+(S.rep.dwor>=20?' Dwór dobrze o was mówi – mam dla was premię.':''),o:[{t:'Zajrzymy do komendantury.',fx:()=>{tab='town';townView='castle'}},{t:'Bywaj, kasztelanie.'}]},
 kupiec:{p:'kupiec',who:'Mikuła, kupiec rzeczny',t:()=>{const r=[];if(!S.q.osadnicy)r.push('W Dąbrowie giną ludzie, włodarz szuka zbrojnych.');if(!S.q.bestia)r.push('W Kręgoszewie łowczyni Bogna szuka kogoś na bestię.');if(!S.q.artefakt)r.push('W stolicy dwa rody kłócą się o jakiś róg.');if(!S.q.skrzydlaci)r.push('Rotmistrz Skrzydlatych w Kręgoszewie podobno szuka śmiałków.');if(!S.q.niepamiec)r.push('W Ustroniu, w lasach za Olszynowem, ludzie zapominają imiona swoich zmarłych.');if(!S.q.kurhan)r.push('Oracz z Olszynowa wykopał pługiem jakiś kurhan.');if(!S.q.dlug)r.push('Kasztelan Borzywoj chce spalić chatę szeptunki, która uleczyła mu syna.');if(!S.q.tropicielka)r.push('W Brzezinie córka leśnika szuka pomocy przeciw wilkom.');if(!S.q.uczen)r.push('Z piwnicy zaklinacza w Weleszowie dochodzi dziwny chichot.');if(!S.q.koscimost)r.push('Na Kamiennym moście znikają podróżni – nie chodźcie tamtędy po zmroku.');if(!S.q.zboze)r.push('W Brzezinie głód, a spichrze Gryfitów pełne.');if(!S.q.polowanie)r.push('Królewski łowczy przepadł w Wilczych Jarach.');return 'Na rzece słychać wszystko! '+(r.length?'Mówią, że… '+r.join(' '):'Ale ostatnio to o was się mówi najwięcej.')},o:[{t:'Dzięki za wieści.'}]},
 kaplan_l:{p:'kaplan',who:'Ojciec Światosław, kanclerz',t:'Świątynia i dwór patrzą na szeptunów nieufnie. Ale ja czytałem kroniki: kręgi kamienne stały tu przed pierwszym kościołem i przed pierwszym królem. Może warto ich słuchać.',o:[{t:'Bywaj, ojcze.'}]},
 /* v18 */
 rus_start:{p:'kupiec',who:'Mirosz, rybak z Sanowa',t:'Moja Dobrawa… Poszła prać na Rozlewiska trzy dni temu. Sąsiedzi słyszeli śpiew nad wodą, a rano tylko wianek pływał przy brzegu.\nLudzie mówią: rusałki. Ja nie mam już siły w to nie wierzyć. Pomożecie?',
  o:[{t:'Odnajdziemy ją.',fx:()=>{S.found.rozlewiska=1;routeFix();qSet('rusalki','szukaj');rep('lud',2);return {txt:'Mirosz ściska wam dłonie. Rozlewiska Utopców pojawiają się na mapie.'}}},{t:'Nie teraz.'}]},
 rus_idle:{p:'kupiec',who:'Mirosz, rybak z Sanowa',t:()=>qS('rusalki')==='done'?(S.fl.rus==='walka'?'Dobrawa wróciła, ale po nocach płacze za „siostrami”. Dziękuję – i proszę, nie mówcie jej, co tam zrobiliście.':'Dobrawa wróciła. Mówi, że rusałka pocałowała ją w czoło na pożegnanie. Niech wam Weles błogosławi.'):'Wieści? Błagam, pospieszcie się.',o:[{t:'Bywaj.'}]},
 rus_meet:{p:'rusalka',who:'Rusałka znad Veleski',t:'Ciii… Dobrawa jest teraz nasza. Tańczy z nami w świetle księżyca i nie czuje już zimna.\nChcecie ją z powrotem? Ludzie zawsze czegoś chcą. A co dacie nam?',
  o:[{t:'Oddaj ją albo zginiesz!',fx:()=>{S.fl.rus='walka';qSet('rusalki','wroc');closeModal();roadFight(['rusalka','utopiec','rusalka'],'Rusałki nad Veleską',{bk:5,st:Math.max(6,S.stage)});return {fight:1}}},
   {t:'Czego chcesz w zamian?',fx:()=>{qSet('rusalki','wianek');return {txt:'„Wianka. Ze Świętego Dębu w Dąbrowie, uplecionego rękami szeptuchy. Ja też kiedyś miałam taki… zanim utonęłam.” Rusałka zanurza się bez plusku.'}}},
   {c:['bard','druid'],t:'Zaśpiewaj z nią pieśń o Kupale',fx:()=>{S.fl.rus='piesn';qSet('rusalki','wroc');rep('duchy',6);return {txt:'Wasze głosy splatają się nad wodą. Rusałka płacze – i wypuszcza Dobrawę z objęć mgły. Dziewczyna jest przemarznięta, ale żywa.'}}},
   {t:'Wrócimy później.'}]},
 rus_wila:{p:'szeptucha',who:'Wila, szeptucha',t:'Wianek dla rusałki? Mądrze. Topielica, która dostanie wianek, przypomina sobie, że była kiedyś dziewczyną. Uplotę go z ziół z dębu – ale zioła kosztują.',
  o:[{t:'Zapłać 40 zł',req:()=>S.gold>=40,rq:'40 zł',fx:()=>{S.gold-=40;qSet('rusalki','wianek2');rep('duchy',2);return {txt:'Wila splata wianek z ruty, bylicy i dębowych liści, szepcząc nad każdym źdźbłem.'}}},
   {c:['druid','kaplan'],t:'Pomóż jej przy obrzędzie',fx:()=>{qSet('rusalki','wianek2');rep('duchy',4);return {txt:'Razem z Wilą odmawiacie stare słowa. Wianek pachnie latem.'}}},{t:'Później.'}]},
 rus_wreath:{p:'rusalka',who:'Rusałka znad Veleski',t:'Wianek… ze Świętego Dębu. Pamiętam zapach ruty. Pamiętam imię… Miłosława. Tak się nazywałam.',
  o:[{t:'Oddaj wianek',fx:()=>{S.fl.rus='wianek';qSet('rusalki','wroc');rep('duchy',8);return {txt:'Rusałka wkłada wianek i rozpływa się w porannej mgle. Na brzegu leży Dobrawa – śpiąca, ciepła, żywa. Obok niej perła z dna Veleski.'}}}]},
 rus_end:{p:'kupiec',who:'Mirosz, rybak z Sanowa',t:'Dobrawa! Córuchno! …Nie wiem, jak wam dziękować. Weźcie wszystko, co odłożyłem – i niech cały Sanów wie, kto ją uratował.',
  o:[{t:'Przyjmij nagrodę',fx:()=>{const t=reward(120+S.stage*10,S.fl.rus==='walka'?null:1);rep('lud',10);qEnd('rusalki',(S.fl.rus==='walka'?'Pokonaliście rusałki i odbiliście Dobrawę siłą. ':'Dobrawa wróciła bez rozlewu krwi – rusałka odnalazła spokój. ')+t);return {txt:'Nagroda: '+t+'. Lud +10'}}},
   {t:'Zatrzymaj złoto dla siebie, Miroszu.',fx:()=>{rep('lud',16);rep('duchy',2);qEnd('rusalki','Odmówiliście zapłaty od biednego rybaka. Sanów długo będzie o tym mówił.');return {txt:'Mirosz ma łzy w oczach. Po porcie szybko rozchodzi się wieść o waszej szczodrości. Lud +16'}}}]},
 pol_start:{p:'starszy',who:'Sołtys Bogumił z Olszynowa',t:'Żniwa stoją. W samo południe na polach pojawia się wysoka biała pani z sierpem i pyta żniwiarzy o rzeczy, których żaden chłop nie wie. Kto nie odpowie – temu kręci głowę.\nTrzech już pochowaliśmy. Pomóżcie!',
  o:[{t:'Wyruszymy na pola i ją pokonamy.',fx:()=>{S.found.pola=1;routeFix();qSet('poludnica','pole');rep('lud',2);return {txt:'Pola Południcy są otwarte na mapie (na południowy zachód od Sanowa).'}}},
   {t:'Może da się ją ułagodzić?',fx:()=>{S.found.krag=1;routeFix();qSet('poludnica','krag');return {txt:'„Babka mówiła, że Południca to dusza dziewczyny zmarłej w dzień ślubu. Przy Kręgu Kamiennym palono dla niej ognie…” Krąg Kamienny widać na mapie.'}}},{t:'Nie teraz.'}]},
 pol_idle:{p:'starszy',who:'Sołtys Bogumił',t:()=>qS('poludnica')==='done'?'Żniwa skończone! W Olszynowie zawsze znajdzie się dla was chleb.':'Czekamy, aż będzie można wyjść w pole.',o:[{t:'Bywaj.'}]},
 pol_krag:{p:'poludnica',who:'Południca',t:'Kto pali ognie przy kamieniach w samo południe? …Pytanie za pytanie, wędrowcze. Co rośnie bez korzenia, biegnie bez nóg i zabiera bez rąk?',
  o:[{t:'Czas.',fx:()=>{S.fl.pol='zagadka';qSet('poludnica','pwroc');rep('duchy',6);return {txt:'Południca uśmiecha się po raz pierwszy od stu lat. „Dobrze… Niech żną. Ale niech zostawią mi ostatni snop.” Znika w drżącym powietrzu.'}}},
   {t:'Woda.',fx:()=>{S.fl.pol='zla';closeModal();qSet('poludnica','pwroc');roadFight(['poludnica','nietoperz'],'Gniew Południcy',{bk:6,st:Math.max(6,S.stage)});return {fight:1}}},
   {c:['bard','mag'],t:'Odpowiedz jej zagadką',fx:()=>{S.fl.pol='zagadka';qSet('poludnica','pwroc');rep('duchy',8);partyHeroes().forEach(h=>gainXp(h,30+S.stage*6));return {txt:'Południca nie zna odpowiedzi na waszą zagadkę i śmieje się jak dziewczyna. „Dawno nikt mnie nie przechytrzył.” (Doświadczenie dla drużyny)'}}}]},
 pol_end:{p:'starszy',who:'Sołtys Bogumił',t:()=>S.fl.pol==='zagadka'?'Ludzie mówią, że w południe na miedzy siedzi biała pani i patrzy na żniwa – ale nikogo nie rusza. Zostawimy jej ostatni snop, jak każe obyczaj.':'Południca przepadła! Wracamy w pole. Oto co zebraliśmy dla was, cała wieś się złożyła.',
  o:[{t:'Dziękujemy.',fx:()=>{const t=reward(100+S.stage*8,1);rep('lud',8);if(S.fl.pol==='zagadka')rep('duchy',4);qEnd('poludnica',(S.fl.pol==='zagadka'?'Ułagodziliście Południcę obyczajem i rozumem. ':'Pokonaliście Południcę. ')+t);return {txt:'Nagroda: '+t}}}]},
 jaga_start:{p:'dziewczyna',who:'Marysia z Mokradeł',t:'Jasio… mój braciszek… Poszedł zbierać chrust na bagna i usłyszałam, jak ktoś go woła słodkim głosem. Potem zatrzeszczało, jakby wielka kura szła przez las.\nTo Baba Jaga! Wszyscy wiedzą, że ona porywa dzieci! Proszę…',
  o:[{t:'Znajdziemy Jasia.',fx:()=>{qSet('jaga','wila');rep('lud',3);return {txt:'„Tylko Wila z Dąbrowy wie, gdzie stoi chata. Babka mówiła, że one się znają.”'}}},{t:'Nie teraz.'}]},
 jaga_idle:{p:'dziewczyna',who:'Marysia z Mokradeł',t:()=>qS('jaga')==='done'?'Jasio już nie chodzi sam na bagna. Dziękujemy wam!':'Proszę, pospieszcie się…',o:[{t:'Bywaj.'}]},
 jaga_wila:{p:'szeptucha',who:'Wila, szeptucha',t:'Jaga… Znam ją. Kiedyś była taka jak ja. Potem zbyt długo rozmawiała z tym, co mieszka pod bagnem.\nChata stoi tam, gdzie bagno styka się z puszczą. Obraca się do wędrowca tyłem – trzeba powiedzieć: „Chatko, chatko, stań do lasu tyłem, a do mnie przodem”.',
  o:[{t:'Pokaż nam drogę.',fx:()=>{S.found.chata=1;regOk();S.reg.lv[7]=1;routeFix();qSet('jaga','chata');rep('duchy',2);return {txt:'Chata na kurzej stopce pojawia się na mapie, na zachodnim skraju bagien. Wyprawa: Chata Baby Jagi.'}}},
   {c:['druid','kaplan','czarnoksieznik'],t:'Daj nam coś przeciw jej czarom.',fx:()=>{S.found.chata=1;regOk();S.reg.lv[7]=1;routeFix();S.bless={name:'Amulet Wili',fx:{defP:.12,heal:.1}};qSet('jaga','chata');return {txt:'Wila zawiesza wam na szyjach woreczki z czosnkiem, solą i jarzębiną. (Amulet Wili: +12% obrony na następną wyprawę). Chata pojawia się na mapie.'}}}]},
 jaga_end:{p:'dziewczyna',who:'Marysia z Mokradeł',t:'Jasio! Żywy! …Co tam było? Nie, nie mówcie. Babka zawsze mówiła, że z chaty Jagi nikt nie wraca. A wy wróciliście.',
  o:[{t:'Weź kufer z chaty dla wsi.',fx:()=>{const t=reward(60+S.stage*6);rep('lud',12);qEnd('jaga','Pokonaliście Babę Jagę i oddaliście jej skarby Mokradłom. '+t);return {txt:'Mokradła będą o was śpiewać. '+t+', Lud +12'}}},
   {t:'Zatrzymaj księgę zaklęć Jagi.',fx:()=>{const t=reward(40,2);rep('duchy',-6);unlockLore('asterion');qEnd('jaga','Księga Baby Jagi jest w waszym plecaku. Niektóre strony szepczą po nocach. '+t);return {txt:'Księga parzy w dłonie. '+t+', Duchy −6'}}}]},
 /* ===== KAMPANIA, Akt I ===== */
 /* --- Wieś, która zapomniała --- */
 nie_start:{p:'dziewczyna',who:'Ludmiła z Ustronia',t:'Przepraszam… my się znamy? Ostatnio wszyscy tu o czymś zapominamy.\nNa cmentarzu jest świeży grób. Na krzyżu wisi mój pierścionek, a ja nie wiem, kto w nim leży. Sąsiadka płacze nad drugim – i też nie pamięta, nad kim. Ludzie mówią, że to klątwa wiedźmy, która mieszkała przy starej kaplicy na wzgórzu. Ale ona umarła wiosną… chyba.',
  o:[{t:'Popytamy we wsi.',go:'nie_wies'},{t:'Pójdziemy prosto do kaplicy.',fx:()=>{S.found.kaplica=1;routeFix();qSet('niepamiec','kaplica');rep('lud',2);return {txt:'Ludmiła wskazuje wzgórze nad wsią. Opuszczona kaplica pojawia się na mapie.'}}},{t:'Nie teraz.'}]},
 nie_wies:{p:'starszy',who:'Dobrogost, sołtys Ustronia',t:'Sołtys długo patrzy w księgę wsi. „Widzicie? Tu zapisano chrzty, śluby, pogrzeby. Moją ręką. A ja nie pamiętam, żebym to pisał.”\nOstatni wpis sprzed sześciu tygodni: „Ojciec Gorzysław zszedł do krypty pod kaplicą z czymś, co przynieśli kupcy z Ruin Asterionu. Mówił, że to dar.” Od tamtej pory nikt go nie widział – i nikt o nim nie pamiętał, aż do teraz.',
  o:[{t:'Idziemy do kaplicy.',fx:()=>{S.found.kaplica=1;routeFix();qSet('niepamiec','kaplica');rep('lud',2);return {txt:'Opuszczona kaplica pojawia się na mapie, na wzgórzu nad wsią.'}}},
   {c:['bard','kaplan'],t:'Odczytajcie na głos imiona z księgi',fx:()=>{S.fl.nieKs=1;S.found.kaplica=1;routeFix();qSet('niepamiec','kaplica');rep('lud',5);return {txt:'Czytacie imiona zmarłych z ostatnich tygodni. Przy piątym Ludmiła zaczyna płakać: „Bronisław… mój Bronek…”. Słowa pomagają – ale tylko na chwilę. Kaplica pojawia się na mapie. +Lud'}}}]},
 nie_idle:{p:'dziewczyna',who:'Ludmiła z Ustronia',t:()=>qS('niepamiec')==='done'?(S.fl.nie==='zabrany'?'Dzień dobry… Przepraszam, czy my się znamy?':'Bronek lubił wieczory nad rzeką. Teraz chodzę tam za niego. Dziękuję wam.'):'Kaplica jest na wzgórzu… Tak mi się wydaje.',o:[{t:'Bywaj.'}]},
 nie_kaplica:{p:'duch',who:'Opuszczona kaplica',t:'Drzwi kaplicy są otwarte, w środku pachnie kurzem i zimnym kamieniem. Na ścianach ktoś wydrapał setki imion – niektóre nachodzą na siebie, jakby piszący bał się, że je zapomni. Pod ołtarzem schody prowadzą do krypty.\nZ dołu dochodzi cichy, równy brzęk. Jak dzwon, którego nie słychać uszami, tylko zębami.',
  o:[{t:'Zejdźcie do krypty',fx:()=>{qSet('niepamiec','krypta');closeModal();roadFight(['upior','szkielet','szkielet'],'Krypta pod kaplicą',{bk:2,qd:'nie_kamien',st:Math.max(4,S.stage)});return {fight:1}}},
   {c:['kaplan','paladyn'],t:'Poświęćcie wodę i zejdźcie z modlitwą',fx:()=>{qSet('niepamiec','krypta');rep('duchy',2);closeModal();roadFight(['upior','szkielet'],'Krypta pod kaplicą',{bk:2,qd:'nie_kamien',st:Math.max(4,S.stage-1)});return {fight:1}}},
   {t:'Wrócimy później.'}]},
 nie_krypta:{p:'duch',who:'Opuszczona kaplica',t:'Schody do krypty wciąż czekają. Brzęk z dołu nie ustaje.',
  o:[{t:'Zejdźcie do krypty',fx:()=>{closeModal();roadFight(['upior','szkielet','szkielet'],'Krypta pod kaplicą',{bk:2,qd:'nie_kamien',st:Math.max(4,S.stage)});return {fight:1}}},{t:'Wrócimy później.'}]},
 nie_kamien:{p:'duch',who:'Krypta pod kaplicą',t:'Upiory rozwiewają się jak dym. Na kamiennym stole leży ojciec Gorzysław – wychudzony, martwy, z uśmiechem na ustach. W dłoniach ściska płaski krąg z czarnego kamienia, pokryty runami, które jarzą się tym samym bladym światłem co pieczęcie Asterionu. To on brzęczy.\nTo nie żadna klątwa wiedźmy. Ten kamień zjada wspomnienia – i chyba żywi się nimi od tysiąca lat.',
  o:[{t:'Rozbijcie kamień',fx:()=>{S.fl.nie='rozbity';unlockLore('kamienie');qSet('niepamiec','wroc');rep('lud',4);return {txt:'Kamień pęka z krzykiem, którego nie słychać. Przez kryptę przelewa się fala cudzych wspomnień – przez chwilę pamiętacie śluby, pogrzeby i kłótnie ludzi, których nigdy nie znaliście. Potem cisza. (Kronika: Czarne kamienie)'}}},
   {c:['mag','czarnoksieznik','kaplan','druid'],t:'Odwróć działanie kamienia',fx:()=>{S.fl.nie='oddany';unlockLore('kamienie');qSet('niepamiec','wroc');rep('duchy',8);rep('lud',6);partyHeroes().forEach(h=>gainXp(h,30+S.stage*6));return {txt:'Odwracacie bieg runów. Kamień oddaje wspomnienia jedno po drugim – ostrożnie, jak matka oddająca dzieci. Wieś odzyska pamięć powoli, bez szaleństwa. Kamień gaśnie na zawsze. (Doświadczenie dla drużyny, Kronika: Czarne kamienie)'}}},
   {t:'Zabierzcie kamień – uczeni w Weleszowie zapłacą krocie',fx:()=>{S.fl.nie='zabrany';S.fl.kamien=1;unlockLore('kamienie');qSet('niepamiec','wroc');rep('lud',-6);rep('duchy',-4);return {txt:'Owijacie kamień w płaszcz. Brzęk cichnie, ale wiecie, że wieś nie odzyska wspomnień, dopóki on istnieje. (Ta decyzja będzie miała konsekwencje.)'}}}]},
 nie_end:{p:'dziewczyna',who:'Ludmiła z Ustronia',t:()=>S.fl.nie==='rozbity'?'Bronek. Mój mąż miał na imię Bronisław. Utonął w Velesce sześć tygodni temu, a ja… zapomniałam go opłakać. Teraz pamiętam wszystko naraz. Boli. Ale to mój ból – i dobrze, że wrócił.':S.fl.nie==='oddany'?'Wspomnienia wracają powoli, jak ptaki na wiosnę. Dziś rano przypomniałam sobie, jak Bronek się śmiał… Dziękuję, że oddaliście nam je tak delikatnie.':'Mówicie, że znaleźliście przyczynę? To dobrze… Przepraszam, o czym mówiliśmy? Pierścionek na krzyżu? Nie wiem, czyj to grób. Ale ładnie, że ktoś go nosi.',
  o:[{t:'Przyjmij podziękowania',fx:()=>{const z=S.fl.nie==='zabrany',t=z?reward(220+S.stage*10,2):reward(110+S.stage*8,1);rep('lud',z?0:8);qEnd('niepamiec',(S.fl.nie==='rozbity'?'Rozbiliście czarny kamień Asterionu pod kaplicą. Ustronie odzyskało pamięć – i żałobę. ':S.fl.nie==='oddany'?'Odwróciliście działanie czarnego kamienia. Ustronie powoli odzyskuje wspomnienia. ':'Zabraliście czarny kamień Asterionu i sprzedaliście wiedzę o nim uczonym. Ustronie wciąż zapomina. ')+t);return {txt:'Nagroda: '+t}}}]},
 /* --- Kurhan bez imienia --- */
 kur_start:{p:'kupiec',who:'Wojsław, oracz z Olszynowa',t:'Orałem nową ziemię za strumieniem, a pług zgrzytnął o kamień. Odkopałem – a tam wejście i schody w dół. Kurhan! Na moim polu!\nOd tej nocy z ziemi słychać szczęk mieczy i rżenie koni. A cała wieś śni o tej samej bitwie: o gwieździe, która spadła z nieba, i o wodzu, który poszedł jej naprzeciw. Rano budzimy się zmęczeni, jakbyśmy walczyli całą noc.',
  o:[{t:'Zejdziemy do kurhanu.',fx:()=>{S.found.kurhan=1;routeFix();qSet('kurhan','kurhan');rep('lud',2);return {txt:'Kurhan bez imienia pojawia się na mapie, na polach na wschód od Olszynowa. Dawni wojownicy nie oddadzą grobu bez walki.'}}},{t:'Nie teraz.'}]},
 kur_idle:{p:'kupiec',who:'Wojsław, oracz z Olszynowa',t:()=>qS('kurhan')==='done'?(S.fl.kur==='straz'?'Nocą na kurhanie stoją wartownicy z włóczniami. Bandyci omijają Olszynów szerokim łukiem.':S.fl.kur==='relikwia'?'Pole po kurhanie zrobiło się jałowe. Ale przynajmniej śpimy.':'Postawiliśmy przy kurhanie kamień. Śpimy jak dzieci.'):'Ta bitwa w snach… Proszę, pospieszcie się.',o:[{t:'Bywaj.'}]},
 kur_rado:{p:'starszy',who:'Radogost, starszy Kurhanowa',t:'Kurhan pod Olszynowem? Hm… Jest stara pieśń. Mówi o wodzu, który poprowadził ludzi przeciw „gwieździe z nieba”, gdy upadał Asterion. Wygrał – ale tak strasznie, że jego lud kazał zapomnieć jego imię, żeby nikt nie poszedł w jego ślady.\nNazywał się Wojmir. Jeśli jego duch wciąż walczy, może imię go uspokoi. Imię to wszystko, co zmarłym zostaje.',
  o:[{t:'Zapamiętamy: Wojmir.',fx:()=>{S.fl.kurImie=1;unlockLore('kurhany');return {txt:'Poznaliście imię wodza z kurhanu. (Kronika: Kurhany przodków)'}}}]},
 kur_wodz:{p:'duch',who:'Wódz bez imienia',t:'Na kamiennym tronie siedzi wódz w zardzewiałej zbroi. Wokół stoją jego wojownicy – martwi od wieków, a wciąż w szyku. W piersi wodza tkwi odłamek czarnego kamienia, żarzący się jak węgiel.\n„Bitwa jeszcze trwa” – mówi głos z wnętrza hełmu. – „Gwiazda wciąż spada. Kim jesteście? I… kim ja jestem?”',
  o:[{t:'Jesteś Wojmir. Twoja bitwa jest wygrana. Odejdź w pokoju.',when:()=>!!S.fl.kurImie,fx:()=>{S.fl.kur='spokoj';rep('duchy',15);rep('lud',4);qSet('kurhan','kwroc');return {txt:'Na dźwięk imienia wódz opuszcza miecz. „Wojmir… Pamiętam.” Odłamek w jego piersi gaśnie. Wojownicy jeden po drugim rozsypują się w popiół, a przez kurhan przechodzi ciepły wiatr. Na tronie zostaje tylko zbroja – i spokój. +Duchy'}}},
   {c:['kaplan','druid'],t:'Odpraw obrzęd pożegnania – bez imienia',when:()=>!S.fl.kurImie,fx:()=>{S.fl.kur='spokoj';rep('duchy',10);qSet('kurhan','kwroc');return {txt:'Odprawiacie stary obrzęd. Wódz długo milczy, a potem kiwa głową. „Niech moje imię zostanie w ziemi.” Duchy odchodzą jeden po drugim. +Duchy'}}},
   {t:'Zostańcie tu na straży Olszynowa.',fx:()=>{S.fl.kur='straz';rep('lud',6);rep('duchy',-4);qSet('kurhan','kwroc');return {txt:'Wódz kiwa głową. „Będziemy stać. Jak zawsze.” Duchy wracają do szyku. Bitewne sny ustaną – ale kurhan już nigdy nie będzie zwykłym grobem. +Lud'}}},
   {t:'Weźcie miecz wodza i odłamek z jego piersi.',fx:()=>{S.fl.kur='relikwia';S.fl.odlamek=1;const t=reward(60,2);rep('duchy',-12);qSet('kurhan','kwroc');return {txt:'Wyrywacie odłamek – wódz krzyczy i rozpada się w pył, a za nim cała drużyna. Miecz jest lekki jak piórko i zimny jak lód. '+t+'. −Duchy (Ta decyzja będzie miała konsekwencje.)'}}}]},
 kur_end:{p:'kupiec',who:'Wojsław, oracz z Olszynowa',t:()=>S.fl.kur==='spokoj'?'Od trzech nocy śpimy jak dzieci! Żadnych bitew, żadnej gwiazdy. Postawimy przy kurhanie kamień'+(S.fl.kurImie?' z imieniem Wojmira – niech ludzie wiedzą.':' – bez imienia, skoro sam tak chciał.'):S.fl.kur==='straz'?'Sny ustały, ale nocą widać na kurhanie wartowników z włóczniami. Nikt w Olszynowie nie boi się już bandytów… tylko trochę ich.':'Sny ustały… ale pole po kurhanie zrobiło się jałowe, a psy wyją na zachód. Dobrze, że nie śpimy już tak jak wtedy. Chyba.',
  o:[{t:'Przyjmij zapłatę',fx:()=>{const t=reward(110+S.stage*8,S.fl.kur==='relikwia'?null:1);rep('lud',6);qEnd('kurhan',(S.fl.kur==='spokoj'?'Duchy wodza Wojmira i jego drużyny odeszły w spokoju. ':S.fl.kur==='straz'?'Duchy z kurhanu strzegą teraz Olszynowa. ':'Zabraliście miecz wodza i odłamek czarnego kamienia z kurhanu. ')+t);return {txt:'Nagroda: '+t}}}]},
 /* --- Dług u Szeptunki --- */
 dlug_start:{p:'kasztelan',who:'Kasztelan Borzywoj',t:'Mój syn, Mszczuj, gorzał w gorączce przez tydzień. Medycy rozkładali ręce, więc posłałem po Jagnę, szeptunkę z lasu. Uzdrowiła go – za cenę, której nie rozumiałem: „Oddasz mi to, czego nie znasz we własnym domu”.\nTeraz chłopak budzi się w nocy i mówi głosami ludzi, których nigdy nie spotkał. Starymi głosami. Dość tego. Pojutrze moi ludzie spalą jej chatę – chyba że wy dowiecie się, co ta wiedźma zrobiła z moim synem.',
  o:[{t:'Porozmawiamy z chłopcem i z Jagną.',fx:()=>{S.found.jagna=1;routeFix();qSet('dlug','rozmowa')},go:'dlug_syn'},
   {t:'Palenie chaty to gruba przesada, kasztelanie.',fx:()=>{S.found.jagna=1;routeFix();qSet('dlug','rozmowa');rep('duchy',2)},go:'dlug_syn'},{t:'Nie mieszamy się w to.'}]},
 dlug_syn:{p:'duch',who:'Mszczuj, syn kasztelana',t:'Chłopak siedzi przy oknie i patrzy w las. Gdy się odzywa, jego usta nie nadążają za słowami, a głos należy do starej kobiety: „Spalili mi chatę, panie. Z dziećmi w środku. Pamiętasz, Borzywoju? Nie, ty nie pamiętasz. To był twój dziad.”\nPotem mruga, uśmiecha się nieśmiało i pyta, czy przywieźliście mu coś z wyprawy.',
  o:[{t:'Ruszamy do chaty Jagny.',fx:()=>({txt:'Chata Jagny pojawiła się na mapie, w lesie na zachód od Kręgoszewa.'})}]},
 dlug_jagna:{p:'szeptunka2',who:'Jagna, szeptunka',t:'Przyszliście mnie spalić czy wysłuchać? …Dobrze.\n„To, czego nie znasz we własnym domu” – tak mówi się na klątwę, której człowiek nie widzi. Dziad Borzywoja spalił chatę szeptuchy razem z jej dziećmi. Jej przekleństwo od trzech pokoleń zabiera pierworodnych. Mszczuj miał umrzeć tej zimy.\nWzięłam od niego tyle klątwy, ile zdołałam unieść. Głosy, które słyszy, to tamte spalone dusze – szukają, kto je wysłucha. Mogę je uwolnić, ale potrzebuję wody z Rozlewisk i popiołu z Kręgu Kamiennego.',
  o:[{t:'Pomożemy.',fx:()=>{S.found.rozlewiska=1;S.found.krag=1;routeFix();qSet('dlug','woda');rep('duchy',3);return {txt:'Jagna kiwa głową. „Woda przed świtem, popiół z ognia dla zmarłych. Wróćcie z jednym i drugim.”'}}},
   {c:['druid','kaplan'],t:'Pozwól, że sprawdzę twoje słowa',fx:()=>{S.fl.dlugPr=1;S.found.rozlewiska=1;S.found.krag=1;routeFix();qSet('dlug','woda');rep('duchy',5);return {txt:'Kładziecie dłoń na jej czole. Klątwa jest prawdziwa – ciężka i stara jak dąb. Jagna nie kłamie. Kasztelan będzie musiał to usłyszeć.'}}},
   {t:'Wiedźmie wierzyć? Kasztelan ma rację.',fx:()=>{S.fl.dlug='spalona';qSet('dlug','dwroc');rep('dwor',4);rep('duchy',-10);return {txt:'Jagna patrzy na was bez gniewu. „Wracajcie więc do pana. Ja poczekam na ogień.”'}}}]},
 dlug_woda:{p:'rusalka',who:'Rusałka znad Veleski',t:()=>(S.fl.rus?'Znowu wy… ':'')+'Woda sprzed świtu, dla szeptunki? Jagna dała mi kiedyś grzebień, gdy jeszcze byłam dziewczyną. Nabierzcie – ale zostawcie coś w zamian. Rzeka nie lubi dawać za darmo.',
  o:[{t:'Wrzuć do wody srebrną monetę (10 zł)',req:()=>S.gold>=10,rq:'10 zł',fx:()=>{S.gold-=10;qSet('dlug','krag');return {txt:'Moneta znika bez plusku. Woda w bukłaku jest zimna jak lód i nie chce się ogrzać.'}}},
   {c:['bard'],t:'Zaśpiewaj rzece',fx:()=>{rep('duchy',2);qSet('dlug','krag');return {txt:'Rusałka nuci razem z wami, a potem sama napełnia wam bukłak.'}}},
   {t:'Nabierzcie wody bez pytania',fx:()=>{qSet('dlug','krag');closeModal();roadFight(['utopiec','utopiec'],'Gniew rzeki',{bk:5,st:Math.max(4,S.stage)});return {fight:1}}}]},
 dlug_krag:{p:'duch',who:'Krąg Kamienny',t:'W środku kręgu leży popiół po ognisku – ciepły, choć nikt tu nie palił od tygodni. Gdy się nachylacie, słyszycie te same stare głosy co u Mszczuja. Tym razem dziękują.',
  o:[{t:'Zbierzcie popiół do woreczka',fx:()=>{qSet('dlug','rytual');return {txt:'Woreczek z popiołem jest dziwnie ciężki. Czas wracać do Jagny.'}}}]},
 dlug_rytual:{p:'szeptunka2',who:'Jagna, szeptunka',t:'Woda i popiół… dobrze. Teraz posłuchajcie, bo obrzęd może skończyć się na różne sposoby, a wybrać musicie wy.\nMogę wypuścić spalone dusze przez siebie – wtedy klątwa zejdzie z rodu Borzywoja na zawsze, ale mnie zabierze ze sobą. Mogę też oddać klątwę tam, skąd przyszła: rodowi, który ją ściągnął. Wtedy chłopak znów zachoruje, a Borzywoj będzie musiał sam przeprosić zmarłych.',
  o:[{t:'Uwolnij ich przez siebie (Jagna odejdzie)',fx:()=>{S.fl.dlug='ofiara';rep('dwor',10);rep('duchy',4);qSet('dlug','dwroc');return {txt:'Jagna uśmiecha się i zamyka oczy. Dusze wychodzą z niej jak ptaki z klatki. Gdy cichnie ostatni głos, szeptunka zasypia przy ognisku – i już się nie budzi. Na stole zostawiła dla was wianek z ruty.'}}},
   {t:'Niech Borzywoj sam spłaci dług przodków',fx:()=>{S.fl.dlug='rod';rep('duchy',10);rep('lud',4);rep('dwor',-6);qSet('dlug','dwroc');return {txt:'Jagna oddaje klątwę rodowi, który ją ściągnął. Daleko w Kręgoszewie Mszczuj znów słabnie – ale dusze mówią przez niego jasno, czego chcą: przeprosin i kurhanu dla spalonych dzieci. To kasztelan musi zrobić. +Duchy'}}},
   {c:['kaplan','druid','bard'],t:'Trzecia droga: wysłuchajcie dusz do końca',fx:()=>{S.fl.dlug='pamiec';rep('duchy',15);rep('lud',6);rep('dwor',4);qSet('dlug','dwroc');partyHeroes().forEach(h=>gainXp(h,30+S.stage*6));return {txt:'Razem z Jagną słuchacie każdego głosu do końca i powtarzacie imiona spalonych dzieci: Zorka, Milko, Bożena. Wysłuchane dusze odchodzą same, nikogo nie zabierając. Jagna płacze ze szczęścia. (Doświadczenie dla drużyny)'}}}]},
 dlug_end:{p:'kasztelan',who:'Kasztelan Borzywoj',t:()=>({ofiara:'Mszczuj śpi spokojnie… a w lesie mówią, że szeptunka umarła. Za mojego syna. Nie wiem, co czuć. Weźcie nagrodę – i nie mówcie mi o niej więcej.',rod:'Przeprosić? Ja, kasztelan, mam klęczeć przed popiołem wiedźmy?! …Mszczuj znowu gorączkuje. Dobrze. Zrobię to. Usypię im kurhan pod lasem. Dziękuję, że powiedzieliście mi prawdę, choć gorzką.',pamiec:'Mój syn się śmieje. Jagna przysłała ziele na sen i kartkę z trzema imionami: Zorka, Milko, Bożena. Kazałem je wyryć na bramie grodu. Kręgoszew nie zapomni.',spalona:'Spłonęła. Mszczuj… nie mówi już cudzymi głosami. Nie mówi wcale. Medycy twierdzą, że to minie. Musi minąć. Weźcie zapłatę.'})[S.fl.dlug]||'No i co z tą wiedźmą?',
  o:[{t:'Przyjmij nagrodę',fx:()=>{const f=S.fl.dlug,t=reward(f==='spalona'?160:130+S.stage*8,f==='pamiec'||f==='ofiara'?1:null,dworMul());rep('dwor',f==='rod'?0:4);qEnd('dlug',({ofiara:'Jagna oddała życie, by zdjąć klątwę z rodu kasztelana. ',rod:'Klątwa wróciła do rodu Borzywoja, a kasztelan musiał przeprosić zmarłych. ',pamiec:'Wysłuchaliście spalonych dusz i uwolniliście je bez ofiar. ',spalona:'Kasztelan spalił chatę Jagny. Jego syn zamilkł. '})[f]+t);return {txt:'Nagroda: '+t}}}]},
 dlug_idle:{p:'kasztelan',who:'Kasztelan Borzywoj',t:'Byliście już u tej wiedźmy? Chata stoi w lesie na zachód od grodu. Czekam – ale niedługo.',o:[{t:'Wkrótce wrócimy.'}]},
 /* --- Pan Czarnego Boru (finał Aktu I) --- */
 bor_start:{p:'wlodar',who:'Pan Dobiesław, włodarz Dąbrowy',t:()=>'Złe wieści z zachodu. Drwale widzieli w Czarnym Borze trolla – wielkiego jak stodoła, z obrożą z czarnego kamienia na karku. Wilki i dziki uciekają przed nim na nasze pola.\nAle to nie wszystko. Przy jego tropach są ślady butów. Ktoś go prowadzi. Ktoś budzi leśne stwory – i chyba wiem, że to nie przypadek, że wszystko zaczęło się, gdy wy zaczęliście grzebać w kamieniach Asterionu.'+(S.fl.osa==='broken'?'\nWila mówi, że moc z rozbitej pieczęci popłynęła właśnie tam.':''),
  o:[{t:'Ruszamy do Czarnego Boru.',fx:()=>{S.found.czarnybor=1;routeFix();qSet('czarnybor','bor');rep('lud',3);return {txt:'Czarny Bór pojawia się na mapie, na zachodnim krańcu puszczy. Na końcu wyprawy czeka Pan Czarnego Boru.'}}},{t:'Musimy się przygotować.'}]},
 bor_win:{p:'szpieg',who:'Człowiek w czarnym płaszczu',t:()=>'Troll pada z łoskotem, od którego drżą korzenie. Na jego karku błyszczy obroża z czarnego kamienia – takiego samego jak '+(S.fl.nie?'w krypcie pod Ustroniem':'na pieczęci z polany')+(S.fl.kur?' i w piersi wodza z kurhanu':'')+'.\nZ gąszczu wychodzi ranny człowiek w czarnym płaszczu. Na piersi ma wyszyty znak: pusty krąg z ośmioma promieniami. „Pustej Gwiazdy nie zatrzymacie” – charczy. – „Każdy kamień, który budzicie albo niszczycie, otwiera szczelinę. Asterion wróci, a Velesia odzyska dawną potęgę…”'+(S.fl.kamien?'\nKamień z kaplicy w waszej torbie zaczyna brzęczeć.':''),
  o:[{t:'Zabierzcie go do Dąbrowy na przesłuchanie',fx:()=>{S.fl.bor='jeniec';unlockLore('gwiazda');qSet('czarnybor','bwroc');rep('dwor',4);return {txt:'Związujecie kultystę. Przez całą drogę milczy i uśmiecha się do gwiazd. (Kronika: Zakon Pustej Gwiazdy)'}}},
   {t:'Odbierzcie mu obrożę i puśćcie wolno – niech zaniesie wieść',fx:()=>{S.fl.bor='wolny';unlockLore('gwiazda');qSet('czarnybor','bwroc');rep('duchy',3);return {txt:'Kultysta znika między drzewami. Obroża w waszych rękach jest ciepła jak żywe serce. (Kronika: Zakon Pustej Gwiazdy)'}}}]},
 bor_end:{p:'wlodar',who:'Pan Dobiesław, włodarz Dąbrowy',t:()=>'Troll z Czarnego Boru nie żyje! Drwale wracają do lasu, a dzieci znów chodzą na jagody.\nZakon Pustej Gwiazdy… czarne kamienie w kaplicy, w kurhanie, na pieczęci. To nie są przypadki, prawda? W Weleszowie muszą się o tym dowiedzieć. A wy – wy już jesteście w samym środku tej historii.',
  o:[{t:'Przyjmij nagrodę',fx:()=>{const t=reward(260+S.stage*10,2,dworMul());rep('lud',12);rep('dwor',6);S.fl.akt=2;qEnd('czarnybor','Pokonaliście Pana Czarnego Boru i odkryliście Zakon Pustej Gwiazdy. Koniec Aktu I. '+t);return {txt:'Nagroda: '+t+'.<br><br><b>Koniec Aktu I: Szepty Velesii.</b> Ciąg dalszy kroniki – Zakon Pustej Gwiazdy – w kolejnych rozdziałach.'}}}]},
 /* ===== unikalni towarzysze ===== */
 /* --- Ignacy, giermek z Kręgoszewa --- */
 ign_start:{p:'ignacy',who:'Ignacy, giermek z Kręgoszewa',t:'Ej, wy! To wy jesteście tą kompanią, o której gadają w koszarach? Weźcie mnie ze sobą! Umiem czyścić zbroje, ostrzyć miecze i… i walczyć też umiem, naprawdę. Rotmistrz Zawisza mówi, że mam serce rycerza, tylko ręce jeszcze za krótkie.\nKasztelan się nie zgadza. Mówi, że puści mnie tylko z kimś, kto wraca z wypraw cały i przyprowadza wszystkich z powrotem.',
  o:[{t:'Pokażemy kasztelanowi, że dbamy o swoich.',fx:()=>{qSet('giermek','proba');rep('dwor',2);return {txt:'Ignacy podskakuje z radości, aż brzęczy mu zbroja. „Będę czekał! I będę ćwiczył codziennie!” (Ukończ wyprawę na poziomie II.)'}}},{t:'Jesteś jeszcze za młody, chłopcze.'}]},
 ign_idle:{p:'ignacy',who:'Ignacy, giermek z Kręgoszewa',t:'Ćwiczę codziennie! Trafiam już w słomianego chochoła dziewięć razy na dziesięć. No… osiem.',o:[{t:'Tak trzymaj.'}]},
 ign_end:{p:'ignacy',who:'Ignacy, giermek z Kręgoszewa',t:'Kasztelan widział, jak wracacie – wszyscy cali! Powiedział, że mogę iść. Powiedział też, żebym słuchał starszych i nie pchał się pierwszy do bitki. Postaram się. Naprawdę.\nMam własny miecz! No, prawie własny. Pożyczony ze zbrojowni.',
  o:[{t:'Witaj w kompanii, Ignacy!',fx:()=>joinUniq('ignacy','giermek','Ignacy, giermek z Kręgoszewa, dołączył do kompanii. Kasztelan kazał mu słuchać starszych.')},{t:'Jeszcze chwilę poczekaj.'}]},
 /* --- Tymek, uczeń zaklinacza --- */
 tym_start:{p:'tymek',who:'Tymek, uczeń zaklinacza',t:'Psst! Tak, wy! Proszę, nie mówcie mistrzowi… Chciałem tylko przeczytać jedno zaklęcie z jego wielkiej księgi. Jedno! Na rozpalanie ognia w kominku. A z księgi wyskoczyły dwa biesy i teraz siedzą w piwnicy, tłuką słoje z konfiturami i śmieją się okropnie.\nMistrz wraca jutro. Pomożecie mi je przegonić? Ja też umiem rzucać czary. Trochę.',
  o:[{t:'Prowadź do piwnicy!',fx:()=>{qSet('uczen','piwnica');closeModal();roadFight(['bies','bies'],'Piwnica zaklinacza',{bk:2,qd:'tym_win',st:Math.max(3,S.stage)});return {fight:1}}},{t:'Może później.'}]},
 tym_piwnica:{p:'tymek',who:'Tymek, uczeń zaklinacza',t:'Biesy dalej siedzą w piwnicy. Słyszycie? Właśnie zjadły wszystkie powidła mistrza.',
  o:[{t:'Tym razem je przegonimy!',fx:()=>{closeModal();roadFight(['bies','bies'],'Piwnica zaklinacza',{bk:2,qd:'tym_win',st:Math.max(3,S.stage)});return {fight:1}}},{t:'Jeszcze nie.'}]},
 tym_win:{p:'tymek',who:'Tymek, uczeń zaklinacza',t:'Ostatni bies z piskiem wskakuje z powrotem do księgi, a Tymek zatrzaskuje okładkę i siada na niej, na wszelki wypadek.\n„Uratowaliście mnie! I powidła… no, połowę powideł. Wiecie co? Mistrz zawsze mówi, że najlepiej uczyć się w drodze. Weźcie mnie ze sobą! Będę grzeczny. I będę czytał zaklęcia do końca, zanim je rzucę.”',
  o:[{t:'Chodź z nami, Tymku!',fx:()=>{if(qS('uczen')==='piwnica')qSet('uczen','czeka');return joinUniq('tymek','uczen','Przegoniliście biesy z piwnicy zaklinacza, a Tymek ruszył z kompanią – uczyć się w drodze.')}},
   {t:'Zostań i ucz się – wrócimy po ciebie.',fx:()=>{qSet('uczen','czeka');return {txt:'„Dobrze… Ale wróćcie szybko!” Tymek macha wam z okna wieży.'}}}]},
 tym_join:{p:'tymek',who:'Tymek, uczeń zaklinacza',t:'Wróciliście! Spakowałem już księgę. Małą. Bez biesów.',
  o:[{t:'Chodź z nami.',fx:()=>joinUniq('tymek','uczen','Przegoniliście biesy z piwnicy zaklinacza, a Tymek ruszył z kompanią – uczyć się w drodze.')},{t:'Jeszcze nie.'}]},
 /* --- Nela z Brzeziny --- */
 nela_start:{p:'nela',who:'Nela z Brzeziny',t:'Cicho… Widzicie te ślady? Wilki. Cała wataha, pięć, może sześć. Co noc podchodzą pod owczarnie, a ojciec ma chorą nogę i nie da rady ich odpędzić.\nSama trafię wilka z pięćdziesięciu kroków. Ale wataha to wataha. Pomożecie? Jak przetrzebimy stado, reszta odejdzie w głąb puszczy.',
  o:[{t:'Zapolujemy na nie.',fx:()=>{qSet('tropicielka','wilki');rep('lud',2);return {txt:'Nela uśmiecha się po raz pierwszy. „Wilki chodzą po Mrocznej Puszczy i po traktach. Zabijcie cztery, a reszta zrozumie.”'}}},{t:'Nie teraz.'}]},
 nela_idle:{p:'nela',who:'Nela z Brzeziny',t:()=>`Ile już wilków? ${(S.q.tropicielka&&S.q.tropicielka.n)||0} z 4. Tropy mówią, że reszta jest blisko.`,o:[{t:'Wkrótce wrócimy.'}]},
 nela_end:{p:'nela',who:'Nela z Brzeziny',t:'Owce całe, ojciec śpi spokojnie, a wataha odeszła za Wilcze Jary – widziałam tropy, szły w pośpiechu.\nWiecie… Brzezina jest mała. Ja chcę zobaczyć Wielki Grzbiet, Bagno Czarne, Smoczą Jamę! Ojciec mówi, że jak już mam iść, to z porządnymi ludźmi. A wy jesteście porządni.',
  o:[{t:'Chodź z nami, Nelu!',fx:()=>joinUniq('nela','tropicielka','Przegoniliście watahę spod Brzeziny, a Nela, córka leśnika, ruszyła z kompanią w świat.')},{t:'Zostań jeszcze przy ojcu.'}]},
 /* --- Karolina z Sanowa --- */
 kar_start:{p:'karolina',who:'Karolina, kapłanka z Sanowa',t:'Pokój z wami, wędrowcy. Jestem Karolina, opiekuję się kościołem nad jeziorem – i każdym, kto przyjdzie tu z raną.\nRybacy mówią, że przy Leśnej kapliczce na zachodzie znikają wędrowcy, a dary w miseczce leżą nietknięte od miesięcy. Ktoś musi zapalić tam światło za tych, którzy nie wrócili. Zaniesiecie świecę? Sama nie mogę zostawić rannych.',
  o:[{t:'Zaniesiemy ją.',fx:()=>{S.found.kapliczka=1;routeFix();qSet('kaplanka','swieca');rep('duchy',2);return {txt:'Karolina owija świecę w lniane płótno i błogosławi waszą drogę. Leśna kapliczka jest na mapie, na zachód od Dąbrowy.'}}},{t:'Nie teraz.'}]},
 kar_idle:{p:'karolina',who:'Karolina, kapłanka z Sanowa',t:'Świeca? Zanieście ją do Leśnej kapliczki, na zachód od Dąbrowy. Niech światło was prowadzi.',o:[{t:'Bywaj, Karolino.'}]},
 kar_kapl:{p:'duch',who:'Leśna kapliczka',t:'Zapalacie świecę od Karoliny. Płomień staje prosto, choć wieje wiatr, a w jego blasku na ścianie kapliczki widać wyryte imiona – wędrowców, którzy kiedyś tędy szli. Gdy rozbłyska ostatnie, z lasu dochodzi cichy szept pełen ulgi.\nW miseczce na dary leży coś nowego: srebrny dzwoneczek.',
  o:[{t:'Zabierz dzwoneczek dla Karoliny',fx:()=>{qSet('kaplanka','kwroc');rep('duchy',4);return {txt:'Dzwoneczek dźwięczy cicho, choć nikt nim nie porusza. Czas wracać do Sanowa.'}}}]},
 kar_end:{p:'karolina',who:'Karolina, kapłanka z Sanowa',t:'Dzwoneczek z kapliczki… Słyszę w nim spokój. Dziękuję – za mnie i za tych, którzy nie wrócili.\nDużo myślałam, gdy was nie było. Ranni przychodzą do mnie z traktów, z gór, z bagien. Może czas, bym to ja poszła tam, gdzie jestem potrzebna, zamiast czekać, aż do mnie przyjdą. Jeśli zechcecie, pójdę z wami.',
  o:[{t:'Będziemy zaszczyceni, Karolino.',fx:()=>joinUniq('karolina','kaplanka','Zanieśliście światło do Leśnej kapliczki, a Karolina, kapłanka z Sanowa, ruszyła z kompanią opatrywać rannych w drodze.')},
   {t:'Twoje miejsce jest tu, przy rannych.',fx:()=>{const t=reward(60+S.stage*5,1);rep('lud',6);S.fl.karolina=1;qEnd('kaplanka','Zanieśliście światło do Leśnej kapliczki. Karolina została w Sanowie, przy rannych. '+t);return {txt:'Karolina kiwa głową z uśmiechem i błogosławi was na drogę. '+t+' (Możesz ją jeszcze zaprosić do kompanii w Sanowie.)'}}}]},
 kar_join:{p:'karolina',who:'Karolina, kapłanka z Sanowa',t:'Wróciliście! Ranni w porcie mają się lepiej. Jeśli wciąż mnie potrzebujecie – pójdę.',
  o:[{t:'Chodź z nami.',fx:()=>{const r=addUniq('karolina');if(S.roster.some(h=>h.uniq==='karolina'))S.fl.karolina=0;return {txt:r}}},{t:'Jeszcze nie.'}]},
 /* ===== zadania poboczne (misje 5–10) ===== */
 /* --- Żelazo pamięta --- */
 zel_start:{p:'starszy',who:'Wojciech, kowal z Wschodniej',t:'Siadajcie, tylko nie na kowadle. Potrzebuję dobrego żelaza, a górnicy z Grzbietu dają same żużle.\nNad jeziorem stała kiedyś kuźnia rodu Żelaznych – wojowników, którzy kuli broń dla pierwszych królów. Woda ją zalała, ale tamtejsze żelazo podobno nie rdzewieje. Utopce się tam kręcą, więc sam nie pójdę. Przyniesiecie mi trochę metalu?',
  o:[{t:'Przyniesiemy.',fx:()=>{S.found.kuznia=1;routeFix();qSet('zelazo','kuznia');return {txt:'Wojciech rysuje węglem drogę na desce. Zatopiona kuźnia pojawia się na mapie, na zachód od Wschodniej, nad brzegiem jeziora.'}}},{t:'Może później.'}]},
 zel_idle:{p:'starszy',who:'Wojciech, kowal z Wschodniej',t:()=>qS('zelazo')==='done'?({kowal:'Ostrze z kuźni Żelaznych wisi nad moim paleniskiem. Czasem dzwoni samo z siebie. Ładnie dzwoni.',bron:'Jak się sprawuje wasze ostrze? Nie rdzewieje, co? Mówiłem.',badacze:'Kanclerz przysłał mi list z podziękowaniem. Pierwszy list w życiu! Powiesiłem go nad drzwiami.'})[S.fl.zel]||'Kuj żelazo, póki gorące.':'Zatopiona kuźnia jest nad jeziorem, na zachód od wsi. Uważajcie na utopce.',o:[{t:'Bywaj, Wojciechu.'}]},
 zel_kuznia:{p:'utopiec',who:'Zatopiona kuźnia',t:'Woda sięga do kolan, a w niej leżą zardzewiałe obręcze, kleszcze i miechy. Kowadło stoi na środku jak kamień ołtarzowy. Gdy podchodzicie bliżej, z mułu podnoszą się dwa utopce – strażnicy, których nikt nie odwołał.',
  o:[{t:'Do broni!',fx:()=>{closeModal();roadFight(['utopiec','utopiec','szlam'],'Strażnicy zatopionej kuźni',{bk:5,qd:'zel_bron',st:Math.max(4,S.stage)});return {fight:1}}},{t:'Wrócimy lepiej przygotowani.'}]},
 zel_bron:{p:'starszy',who:'Zatopiona kuźnia',t:'Pod kowadłem, w skrzyni owiniętej woskowanym płótnem, leży miecz. Ani śladu rdzy. Gdy ktoś z czarodziejskim darem bierze go do ręki, ostrze zaczyna cicho dzwonić, a na głowni pojawiają się runy – takie same jak na kamieniach Asterionu.\nKowal chciał tylko żelaza. To jest coś więcej.',
  o:[{t:'Oddajmy miecz kowalowi – taka była umowa',fx:()=>{S.fl.zel='kowal';qSet('zelazo','zwroc');return {txt:'Owijacie miecz z powrotem w płótno. Wojciech będzie wiedział, co z nim zrobić.'}}},
   {t:'Zatrzymajmy go dla kompanii',fx:()=>{S.fl.zel='bron';const it=makeItem(Math.max(3,S.stage+1),3,'miecz');it.n='Miecz rodu Żelaznych';it.st.atk=(it.st.atk||0)+3;it.price=Math.round(it.price*1.5);if(S.inv.length<INV_MAX)S.inv.push(it);else S.gold+=it.price;rep('lud',-2);qSet('zelazo','zwroc');return {txt:'Miecz rodu Żelaznych trafia do plecaka (legendarny). Kowalowi zaniesiecie zwykłe żelazo z kuźni – i wyjaśnienie.'}}},
   {t:'Zanieśmy go badaczom Asterionu w Weleszowie',fx:()=>{S.fl.zel='badacze';qSet('zelazo','badacze');return {txt:'Takie runy powinien zobaczyć ktoś, kto czyta stare kroniki. Ojciec Światosław w Weleszowie zbiera wszystko, co dotyczy Asterionu.'}}}]},
 zel_bad:{p:'kaplan',who:'Ojciec Światosław, kanclerz',t:'Miecz z kuźni Żelaznych? Pokażcie… Na Welesa! Te runy to nie zdobienie, tylko zapis. Ktoś wykuł w ostrzu pieczęć – maleńką, ale prawdziwą. Ród Żelaznych nie tylko kuł broń dla królów. Strzegł czegoś.\nZachowam go w archiwum, z dala od ciekawskich. Kancelaria wynagrodzi was za to – i za dyskrecję.',
  o:[{t:'Przekaż miecz kanclerzowi',fx:()=>{const t=reward(140+S.stage*8,1,dworMul());rep('dwor',8);rep('duchy',4);unlockLore('kamienie');qSet('zelazo','zwroc');return {txt:'Kanclerz zamyka miecz w okutej skrzyni. '+t+'. +Dwór, +Duchy (Kronika: Czarne kamienie). Kowalowi z Wschodniej należy się jeszcze zwykłe żelazo z kuźni.'}}}]},
 zel_end:{p:'starszy',who:'Wojciech, kowal z Wschodniej',t:()=>({kowal:'Miecz? Z kuźni Żelaznych?! I nie zardzewiał… Słuchajcie, przekuję go na coś dla was – takie żelazo nie powinno leżeć w skrzyni. Dajcie mi dzień.',bron:'Zatrzymaliście miecz? No cóż, znalezione nie kradzione. Ale żelazo przynieśliście, to i zapłacę – choć mniej.',badacze:'Kanclerz go wziął? Ha! Wiedziałem, że to nie zwykła klinga. Żelazo z kuźni wystarczy mi na całą zimę.'})[S.fl.zel]||'',
  o:[{t:'Przyjmij zapłatę',fx:()=>{const z=S.fl.zel,t=z==='kowal'?reward(80+S.stage*5,2):reward(z==='bron'?50:90+S.stage*4,null);rep('lud',z==='bron'?2:6);qEnd('zelazo',({kowal:'Oddaliście miecz rodu Żelaznych kowalowi z Wschodniej, a on przekuł go dla was. ',bron:'Zatrzymaliście miecz rodu Żelaznych dla kompanii. ',badacze:'Miecz rodu Żelaznych trafił do archiwum kanclerza w Weleszowie. '})[z]+t);return {txt:'Nagroda: '+t}}}]},
 /* --- Ostatnie polowanie --- */
 low_start:{p:'rycerz',who:'Mścisław, koniuszy królewski',t:'Łowczy królewski Sobiesław pojechał tydzień temu do Wilczych Jarów i nie wrócił. Najlepszy tropiciel w Velesii, zna puszczę jak własną kieszeń. Ludzie, których posłałem za nim, wrócili bez słowa – mówią tylko, że w Jarach wilki nie atakują. Stoją i patrzą.\nKról chce mieć łowczego z powrotem przed jesiennymi łowami. Żywego, jeśli się da.',
  o:[{t:'Odnajdziemy go.',fx:()=>{S.found.jary=1;qSet('polowanie','jary');routeFix();rep('dwor',2);return {txt:'Mścisław kiwa głową. „Wilcze Jary są na północy, za Dąbrową.” (Ukończ dowolną wyprawę do Wilczych Jarów.)'}}},{t:'Nie teraz.'}]},
 low_idle:{p:'rycerz',who:'Mścisław, koniuszy królewski',t:()=>qS('polowanie')==='done'?(S.fl.low==='wilk'?'Sobiesław zawiesił skórę białej wilczycy w sali łowieckiej. Mówi, że wolałby jej tam nie widzieć.':'Sobiesław znowu jeździ do Jarów. Mówi, że teraz poluje tylko tam, gdzie las mu pozwala.'):'Wilcze Jary są na północy, za Dąbrową. Pospieszcie się.',o:[{t:'Bywaj, panie.'}]},
 low_wilk:{p:'bestia',who:'Biała wilczyca',t:'W najgłębszym jarze, pod korzeniami zwalonego buka, leży łowczy Sobiesław – ranny, ale żywy, opatrzony mchem. Nad nim stoi biała wilczyca. Nie warczy. Patrzy na was, a potem na drugi koniec jaru, gdzie w błocie widać ślady czegoś ciężkiego, z ogonem jak u jaszczura.\n„Ona mnie nie napadła” – szepcze łowczy. – „Ona mnie przed tym ukryła. Zwierzęta uciekają z Jarów przed potworem…”',
  o:[{t:'Idźmy za wilczycą – zabijmy potwora',fx:()=>{S.fl.low='potwor';closeModal();roadFight(['bazyliszek','pajak','pajak'],'Potwór z Wilczych Jarów',{bk:0,qd:'low_po',st:Math.max(6,S.stage)});return {fight:1}}},
   {c:['druid'],t:'Przemów do wilczycy w mowie lasu',fx:()=>{S.fl.low='potwor';rep('duchy',4);closeModal();roadFight(['bazyliszek','pajak'],'Potwór z Wilczych Jarów',{bk:0,qd:'low_po',st:Math.max(5,S.stage-1)});return {fight:1}}},
   {t:'Biała skóra to królewskie trofeum – zabijcie wilczycę',fx:()=>{S.fl.low='wilk';rep('duchy',-10);rep('dwor',4);qSet('polowanie','wroc');S.tro.wilk=(S.tro.wilk||0)+3;return {txt:'Wilczyca nie broni się. Pada bez jednego warknięcia, a las wokół milknie. Łowczy odwraca wzrok. Potwór wciąż jest gdzieś w Jarach… −Duchy, +Dwór'}}}]},
 low_po:{p:'bestia',who:'Biała wilczyca',t:'Bazyliszek wali się w błoto, a jego kamienne spojrzenie gaśnie. Biała wilczyca podchodzi do łowczego, trąca go nosem w dłoń – i znika między drzewami. Po chwili z głębi jaru słychać wycie całej watahy. Wracają do domu.',
  o:[{t:'Zabierzcie łowczego do Weleszowa',fx:()=>{rep('duchy',8);qSet('polowanie','wroc');return {txt:'Sobiesław opiera się na waszym ramieniu. „Polowałem w tych lasach trzydzieści lat. Pierwszy raz to las zapolował dla mnie.” +Duchy'}}}]},
 low_end:{p:'rycerz',who:'Mścisław, koniuszy królewski',t:()=>S.fl.low==='wilk'?'Łowczy żyje – i przywieźliście białą skórę! Król będzie zachwycony. Sobiesław jakoś mniej… ale to minie.':'Sobiesław żyje i opowiada o białej wilczycy, która go uratowała. Gdyby nie wy, dworscy uczeni mieliby go za szaleńca. Król was wynagrodzi.',
  o:[{t:'Przyjmij nagrodę',fx:()=>{const w=S.fl.low==='wilk',t=reward(w?200:160+S.stage*8,w?null:1,dworMul());rep('dwor',8);qEnd('polowanie',(w?'Uratowaliście łowczego Sobiesława i przywieźliście skórę białej wilczycy. ':'Uratowaliście łowczego Sobiesława i zabiliście potwora z Wilczych Jarów. Wilki wróciły do domu. ')+t);return {txt:'Nagroda: '+t+'. +Dwór'}}}]},
 /* --- Zboże dla głodnych --- */
 zb_start:{p:'starszy',who:'Zdzich, sołtys Brzeziny',t:'Żniwa się nie udały – grad wybił połowę zboża, a resztę zjadła rdza. Dzieci jedzą placki z żołędzi. A w Sanowie spichrze pana Bogusza z Gryfitów pękają w szwach! Trzyma ziarno i czeka, aż cena skoczy trzy razy.\nPomóżcie. Jakkolwiek. Przed zimą musimy mieć zboże.',
  o:[{t:'Kupimy zboże w Sanowie i przeprowadzimy wozy',fx:()=>{qSet('zboze','eskorta');rep('lud',2);return {txt:'„Kupcy z Sanowa nie boją się Gryfitów, boją się lasu” – mówi sołtys. „Z eskortą sprzedadzą uczciwie.”'}}},
   {t:'Ujawnijmy, co robi pan Bogusz',fx:()=>{qSet('zboze','dowody');rep('lud',2);return {txt:'„Kanclerz w Weleszowie nie lubi, jak ktoś głodzi królewskich chłopów. Ale bez dowodów nic nie zrobi.”'}}},
   {t:'Poszukajmy zboża gdzie indziej – w Olszynowie',fx:()=>{qSet('zboze','olszynow');rep('lud',2);return {txt:'„Olszynów zawsze ma nadwyżki, tylko Bogumił jest skąpy jak sroka.”'}}},{t:'Nie teraz.'}]},
 zb_idle:{p:'starszy',who:'Zdzich, sołtys Brzeziny',t:()=>qS('zboze')==='done'?({eskorta:'Na placu pachnie chlebem! Wozy z Sanowa dojechały co do jednego. Kupcy mówią, że teraz będą przyjeżdżać co miesiąc.',ujawnij:'Gryfici musieli otworzyć spichrze. Zboże po starej cenie! Pan Bogusz omija Brzezinę szerokim łukiem, ale kto by za nim płakał.',olszynow:'Olszynów i Brzezina pierwszy raz od lat jedzą z jednej misy. Bogumił nawet przyjechał na dożynki.'})[S.fl.zboze]||'Dziękujemy wam.':'Pomóżcie, zanim przyjdzie zima.',o:[{t:'Bywaj, Zdzichu.'}]},
 zb_eskorta:{p:'kupiec',who:'Mikuła, kupiec rzeczny',t:'Zboże dla Brzeziny? Sprzedam po uczciwej cenie, Gryfici mogą mi skoczyć. Ale wozy muszą przejechać przez las, a tam ostatnio grasują zbóje – ktoś im chyba dobrze płaci, żeby zboże nie dotarło do wsi…',
  o:[{t:'Ruszamy z wozami',fx:()=>{closeModal();roadFight(['bandyta','rzezimieszek','lucznikB','bandyta'],'Napad na wozy ze zbożem',{bk:1,qd:'zb_dowiezione',st:Math.max(4,S.stage)});return {fight:1}}},{t:'Jeszcze chwilę.'}]},
 zb_dowiezione:{p:'kupiec',who:'Mikuła, kupiec rzeczny',t:'Zbóje uciekają w las, a jeden z nich gubi sakiewkę z herbem… gryfa. Wozy toczą się dalej. Do Brzeziny dojadą przed zmrokiem.',
  o:[{t:'Odprowadźcie wozy do Brzeziny',fx:()=>{S.fl.zboze='eskorta';rep('lud',6);rep('dwor',-2);qSet('zboze','zwroc');return {txt:'Wozy pełne worków skrzypią na trakcie. +Lud'}}}]},
 zb_mikula:{p:'kupiec',who:'Mikuła, kupiec rzeczny',t:'Ile worków wpłynęło do spichrzy Gryfitów? Ha! Ja liczę każdy worek, co płynie Veleską – trzy tysiące od żniw. Mam to zapisane w księdze, z datami i pieczęciami przewoźników. Ale jak wam ją dam, Gryfici się dowiedzą skąd…',
  o:[{t:'Zapłać za odpis z księgi (50 zł)',req:()=>S.gold>=50,rq:'50 zł',fx:()=>{S.gold-=50;qSet('zboze','ujawnij');return {txt:'Mikuła przepisuje strony z księgi i przybija swoją pieczęć. „Tylko nie mówcie, od kogo to macie.”'}}},
   {c:['bard','lotr'],t:'Przekonaj go, że Gryfici nie poznają źródła',fx:()=>{qSet('zboze','ujawnij');rep('lud',2);return {txt:'Mikuła śmieje się i wręcza wam odpis za darmo. „Dla głodnych dzieci – niech będzie.”'}}},{t:'Wrócimy później.'}]},
 zb_kanclerz:{p:'kaplan',who:'Ojciec Światosław, kanclerz',t:'Trzy tysiące worków? W roku głodu? To nie handel, to rozbój. Król zakazał trzymania zboża ponad potrzebę, gdy chłopi głodują – stary przywilej, ale wciąż obowiązuje.\nPan Bogusz z Gryfitów otworzy spichrze jeszcze w tym tygodniu. Po starej cenie. Dopilnuję tego osobiście.',
  o:[{t:'Dziękujemy, ojcze.',fx:()=>{S.fl.zboze='ujawnij';rep('lud',8);rep('dwor',4);qSet('zboze','zwroc');return {txt:'Kanclerz pieczętuje rozkaz. Ród Gryfitów tego nie zapomni – ale Brzezina też nie. +Lud, +Dwór'}}}]},
 zb_olsz:{p:'starszy',who:'Bogumił, sołtys Olszynowa',t:'Zboże dla Brzeziny? Mamy nadwyżki, to prawda. Ale nadwyżki to nasze zabezpieczenie na zły rok. Czemu mam oddawać ziarno wsi, która nigdy nam nie pomogła?',
  o:[{t:'Zapłać za zboże (80 zł)',req:()=>S.gold>=80,rq:'80 zł',fx:()=>{S.gold-=80;S.fl.zboze='olszynow';rep('lud',6);qSet('zboze','zwroc');return {txt:'Bogumił liczy monety dwa razy, a potem każe ładować wozy. +Lud'}}},
   {when:()=>qS('poludnica')==='done',t:'Pomogliśmy wam z Południcą. Teraz wy pomóżcie sąsiadom',fx:()=>{S.fl.zboze='olszynow';rep('lud',8);qSet('zboze','zwroc');return {txt:'Bogumił drapie się po głowie. „Niech będzie. Kto pomógł nam, temu nie odmówię.” Wozy ruszają do Brzeziny. +Lud'}}},
   {c:['bard'],t:'Zaśpiewaj o dobrym sąsiedztwie',fx:()=>{S.fl.zboze='olszynow';rep('lud',8);qSet('zboze','zwroc');return {txt:'Pół wsi płacze ze wzruszenia, a Bogumił każe ładować wozy, zanim zdąży się rozmyślić. +Lud'}}},{t:'Wrócimy później.'}]},
 zb_end:{p:'starszy',who:'Zdzich, sołtys Brzeziny',t:()=>({eskorta:'Wozy dojechały! Kupcy z Sanowa mówią, że zbóje mieli sakiewki z gryfem. Ale nieważne – dzieci będą jadły chleb, nie żołędzie.',ujawnij:'Kanclerz kazał otworzyć spichrze! Zboże po starej cenie! Brzezina tego nie zapomni.',olszynow:'Zboże z Olszynowa! Bogumił, ten skąpiec… Pójdę mu podziękować. Może nawet zaproszę go na dożynki.'})[S.fl.zboze]||'',
  o:[{t:'Przyjmij podziękowania',fx:()=>{const t=reward(60+S.stage*5,1);rep('lud',8);qEnd('zboze',({eskorta:'Przeprowadziliście wozy ze zbożem z Sanowa do Brzeziny. ',ujawnij:'Zdemaskowaliście Gryfitów przed kanclerzem – spichrze otwarto. ',olszynow:'Przekonaliście Olszynów, by pomógł Brzezinie. '})[S.fl.zboze]+t);return {txt:'Cała wieś składa się dla was na prezent: '+t+'. +Lud'}}}]},
 /* --- Most z kości --- */
 km_wybor:{p:'straznik',who:'Strażnik mostu',t:'Most stoi tu od czasów pierwszych królów i ani jednego kamienia nie brakuje. A jednak co tydzień ktoś wchodzi na niego z jednej strony i nie schodzi z drugiej.\nZejdźcie na brzeg, to zobaczycie: pod przęsłami leżą kości. Stare i świeże. Nikt nie wie, czyje. Stary przewoźnik Bolko twierdzi, że w skarpie jest jaskinia, do której da się dopłynąć – ale bez zapłaty nawet nie chce o tym gadać.',
  o:[{t:'Zastawcie pułapkę na moście w nocy',fx:()=>{S.fl.km='pulapka';closeModal();roadFight(['utopiec','utopiec','ghul','ghul'],'Noc na moście',{bk:5,qd:'km_win',st:Math.max(5,S.stage)});return {fight:1}}},
   {c:['druid','lucznik','lotr'],t:'Zbadajcie brzeg rzeki',fx:()=>{S.fl.km='trop';closeModal();roadFight(['utopiec','ghul','ghul'],'Jaskinia pod mostem',{bk:2,qd:'km_win',st:Math.max(4,S.stage)});return {fight:1}}},
   {t:'Zapłać przewoźnikowi Bolkowi (30 zł)',req:()=>S.gold>=30,rq:'30 zł',fx:()=>{S.gold-=30;S.fl.km='lodz';closeModal();roadFight(['utopiec','ghul'],'Jaskinia pod mostem',{bk:2,qd:'km_win',st:Math.max(4,S.stage-1)});return {fight:1}}},
   {t:'Wrócimy później.'}]},
 km_win:{p:'straznik',who:'Jaskinia pod mostem',t:()=>(S.fl.km==='pulapka'?'O północy z wody wypełzły utopce i ghule – czekały na samotnego wędrowca, a trafiły na kompanię. Ostatni ucieka do jaskini w skarpie, a wy za nim.\n':S.fl.km==='lodz'?'Łódź Bolka wpływa do jaskini bez jednego plusku. Zaskoczone stwory nie zdążyły nawet krzyknąć.\n':'Ślady w mule prowadzą do szczeliny w skarpie. W środku czekały stwory – ale wy byliście szybsi.\n')+'W głębi jaskini, na stosie kości podróżnych, leży sakwa poborcy myta, zbutwiałe tobołki i kilka sakiewek. Sto lat ofiar. Jedne kości mają resztki płaszczy kupieckich, inne – kolczugi.',
  o:[{t:'Pochowajcie kości i oddajcie rzeczy rodzinom',fx:()=>{const t=reward(60+S.stage*5,1);rep('duchy',10);rep('lud',6);qEnd('koscimost','Oczyściliście jaskinię pod Kamiennym mostem i pochowaliście kości podróżnych. Most jest znowu bezpieczny. '+t);return {txt:'Na brzegu wyrasta kopiec z kamieniem. Strażnik mostu zdejmuje czapkę. '+t+'. +Duchy, +Lud'}}},
   {t:'Zabierzcie, co cenne – zmarłym się nie przyda',fx:()=>{const t=reward(140+S.stage*8,2);rep('duchy',-8);qEnd('koscimost','Oczyściliście jaskinię pod Kamiennym mostem i zabraliście skarby zmarłych. Most jest bezpieczny, ale kości leżą tam nadal. '+t);return {txt:'Sakwy są ciężkie. Wychodząc, słyszycie za plecami cichy stukot kości o kości. '+t+'. −Duchy'}}}]},
 /* --- Noc ognia --- */
 og_start:{p:'dziewczyna',who:'Mira z rodu Sowińskich',t:'Za trzy dni Noc Kupały, a ktoś ukradł Maskę Przodków – tę, w której starszy tańczy przy ognisku, żeby zmarli wiedzieli, gdzie wrócić na jedną noc.\nMoja rodzina, Sowińscy, mówi, że to Koźlakowie, bo od lat chcą nosić maskę. Koźlakowie mówią, że to my, żeby ich oczernić. Mój brat ostrzy siekierę. Jeśli maska się nie znajdzie, w Kurhanowie poleje się krew.',
  o:[{t:'Zbierzmy oba rody przy ognisku i porozmawiajmy',go:'og_rody'},
   {c:['lotr','lucznik','druid'],t:'Obejrzyjcie miejsce kradzieży',fx:()=>{S.found.ruiny=1;routeFix();qSet('ogien','ruiny');return {txt:'Pod oknem chaty starszego – ślady butów, których nikt w Kurhanowie nie nosi: podkute, miejskie. Prowadzą za kurhany, do Ruin Asterionu. Obok w błocie leży zgubiony medalion: pusty krąg z ośmioma promieniami.'}}},
   {t:'Zaczajcie się na złodziei w noc święta',fx:()=>{closeModal();roadFight(['kultysta','kultysta','bies'],'Złodzieje Maski Przodków',{bk:2,qd:'og_maska',st:Math.max(4,S.stage)});return {fight:1}}},{t:'Może później.'}]},
 og_rody:{p:'starszy',who:'Ognisko w Kurhanowie',t:'Przy ognisku siedzą dwie rodziny po dwóch stronach ognia. Stary Koźlak stuka laską, młody Sowiński trzyma rękę przy pasie. Wszyscy mówią naraz.\nGdy w końcu milkną, najmłodsza z Koźlaków, mała dziewczynka, mówi cicho: „A ja widziałam pana z gwiazdką. Wyszedł od dziadka Radogosta przez okno.”',
  o:[{t:'Jaka gwiazdka? Opowiedz.',fx:()=>{S.found.ruiny=1;routeFix();rep('lud',4);qSet('ogien','ruiny');return {txt:'„Taka pusta, z ośmioma promykami. Na płaszczu. Poszedł w stronę starych kamieni za kurhanami.” Oba rody patrzą na siebie – po raz pierwszy od lat bez wrogości. Ruiny Asterionu są na mapie. +Lud'}}},
   {c:['bard','kaplan'],t:'Przypomnij im, czym jest Noc Kupały',fx:()=>{S.found.ruiny=1;routeFix();rep('lud',6);rep('duchy',2);qSet('ogien','ruiny');return {txt:'Mówicie o zmarłych, którzy wracają na jedną noc – do obu rodów, bo w kurhanach leżą razem. Starzy kiwają głowami, a dziewczynka opowiada o „panu z gwiazdką”, który uciekł w stronę Ruin Asterionu. +Lud, +Duchy'}}}]},
 og_ruiny:{p:'szpieg',who:'Ruiny Asterionu',t:'Między kolumnami płonie zimny, niebieski ogień. Trzech ludzi w czarnych płaszczach ze znakiem pustej gwiazdy kładzie Maskę Przodków na kamiennym stole i śpiewa w mowie, której nikt w Velesii nie zna. Runy na łuku jarzą się coraz mocniej.\n„Maska otwiera drogę zmarłym” – mówi jeden z nich. – „A my potrzebujemy drogi.”',
  o:[{t:'Przerwijcie obrzęd!',fx:()=>{closeModal();roadFight(['kultysta','kultysta','szeptun'],'Obrzęd w Ruinach Asterionu',{bk:2,qd:'og_maska',st:Math.max(5,S.stage)});return {fight:1}}},{t:'Wycofajcie się.'}]},
 og_maska:{p:'dziewczyna',who:'Maska Przodków',t:'Maska jest cała – drewniana twarz z oczami z bursztynu, okuta srebrem. Złodzieje nosili medaliony z pustą gwiazdą o ośmiu promieniach. Zanim ostatni uciekł, krzyknął: „Pusta Gwiazda pamięta Kurhanów!”\nNiedobrze. Ale najpierw – maska musi wrócić przed Nocą Kupały.',
  o:[{t:'Zanieście maskę do Kurhanowa',fx:()=>{qSet('ogien','wroc');return {txt:'Owijacie maskę w płaszcz. Bursztynowe oczy wydają się patrzeć przez materiał.'}}}]},
 og_end:{p:'dziewczyna',who:'Mira z rodu Sowińskich',t:'Maska! Cała! I Koźlakowie, i Sowińscy… nie wiedzą, co powiedzieć. Pierwszy raz od pokoleń będą tańczyć przy jednym ogniu.\nKto nosił ten znak, pustą gwiazdę? Starszy Radogost mówi, że widział go już kiedyś, na kamieniach Asterionu. I że to zły znak.',
  o:[{t:'Niech maskę nosi ktoś z obu rodów naraz',fx:()=>{const t=reward(70+S.stage*6,1);rep('lud',8);rep('duchy',6);qEnd('ogien','Odzyskaliście Maskę Przodków z rąk ludzi ze znakiem Pustej Gwiazdy. Kurhanów świętował Noc Kupały razem, a maskę niosły oba rody. '+t);return {txt:'W Noc Kupały Mira z Sowińskich i młody Koźlak niosą maskę razem, a ogień płonie wyżej niż kiedykolwiek. '+t+'. +Lud, +Duchy'}}},
   {t:'Oddajcie maskę starszemu Radogostowi',fx:()=>{const t=reward(90+S.stage*6,null);rep('lud',4);rep('duchy',4);qEnd('ogien','Odzyskaliście Maskę Przodków z rąk ludzi ze znakiem Pustej Gwiazdy i oddaliście ją starszemu Kurhanowa. '+t);return {txt:'Radogost przyjmuje maskę z namaszczeniem i płaci z kasy osady. '+t+'. +Lud, +Duchy'}}}]},
 og_wait:{p:'dziewczyna',who:'Mira z rodu Sowińskich',t:()=>qS('ogien')==='ruiny'?'Ruiny Asterionu są za kurhanami, na południe. Pospieszcie się – do Nocy Kupały zostały trzy dni.':'Jak chcecie szukać maski?',
  o:[{when:()=>!S.q.ogien,t:'Opowiedz jeszcze raz',go:'og_start'},{t:'Wkrótce wrócimy.'}]},
 og_idle:{p:'dziewczyna',who:'Mira z rodu Sowińskich',t:'Koźlakowie zaprosili nas na żniwa. Na żniwa! Babcia mówi, że świat się kończy. Ja mówię, że się zaczyna.',o:[{t:'Bywaj, Miro.'}]},
 /* --- Ostatni sygnał --- */
 syg_start:{p:'straznik',who:'Jarema, stary strażnik',t:'Byłem kiedyś strażnikiem na wieży sygnałowej pod górami. Opuścili ją, zanim się urodziłem – a ja i tak pilnowałem jej z przyzwyczajenia, aż kolano odmówiło.\nOd tygodnia, co noc, na szczycie znowu pali się światło. Białe, równe, bez dymu. Żaden ogień tak nie świeci. Sprawdzicie, kto tam siedzi? Ja już nie wejdę po tych schodach.',
  o:[{t:'Sprawdzimy.',fx:()=>{S.found.straznica=1;routeFix();qSet('sygnal','wieza');return {txt:'Jarema pokazuje laską na południe. Strażnica jest na mapie.'}}},{t:'Może później.'}]},
 syg_idle:{p:'straznik',who:'Jarema, stary strażnik',t:()=>qS('sygnal')==='done'?(S.fl.syg==='zgas'?'Wieża znowu ciemna. Jakoś mi smutno. Pilnowałem jej tyle lat.':'Światło na wieży świeci co noc. Teraz wiem, że ktoś je zapalił dla nas. Śpię spokojniej.'):'Strażnica jest na południe stąd, u stóp gór. Uważajcie na schody.',o:[{t:'Bywaj, Jaremo.'}]},
 syg_wieza:{p:'duch',who:'Szczyt Strażnicy',t:'Na szczycie wieży nikogo nie ma. Na środku stoi mechanizm z czarnego kamienia: pierścienie z runami obracają się powoli, a w środku płonie kryształ jasny jak gwiazda. Promień światła bije prosto na wschód, ku Martwym Ziemiom.\nObok, w skrzynce przybitej do muru, leży dziennik ostatniego strażnika. Ostatni wpis, sprzed sześćdziesięciu lat: „Mechanizm zapalił się sam. Uczeni z Weleszowa mówią, że to ostrzeżenie. Gwiazdy, które spadły na Asterion, nie spadły same. Zostały ściągnięte. Ktoś je wezwał. A to światło zapali się znowu, gdy ktoś spróbuje wezwać je ponownie.”',
  o:[{t:'Zgaście mechanizm',fx:()=>{S.fl.syg='zgas';unlockLore('sygnal');qSet('sygnal','wroc');return {txt:'Wyjmujecie kryształ. Pierścienie stają, światło gaśnie. Kryształ jest ciepły i lekko brzęczy. (Kronika: Ostatni sygnał)'}}},
   {t:'Zostawcie światło – niech ostrzega',fx:()=>{S.fl.syg='swiatlo';rep('duchy',4);unlockLore('sygnal');qSet('sygnal','wroc');return {txt:'Zabieracie tylko dziennik strażnika. Promień dalej bije na wschód. Ktoś tam, daleko, też musi go widzieć. (Kronika: Ostatni sygnał) +Duchy'}}},
   {c:['mag','czarnoksieznik','bard'],t:'Odczytajcie runy na pierścieniach',fx:()=>{S.fl.syg='swiatlo';partyXp(40+S.stage*6);unlockLore('sygnal');unlockLore('asterion');qSet('sygnal','wroc');return {txt:'Runy to nie zaklęcie, tylko zapis: daty, gwiazdy, kierunki. Mechanizm liczy noce do czegoś. Liczba jest już bardzo mała. (Doświadczenie dla drużyny, Kronika: Ostatni sygnał)'}}}]},
 syg_end:{p:'straznik',who:'Jarema, stary strażnik',t:()=>'Mechanizm? Gwiazdy ściągnięte z nieba? …Mój dziadek mówił, że Asterion nie przegrał żadnej wojny. Że po prostu jednej nocy niebo spadło mu na głowę. Myślałem, że to bajka dla dzieci.'+(S.fl.syg==='zgas'?' A wy zgasiliście to światło. Może to i lepiej – ale chyba nie chcę wiedzieć, przed czym ostrzegało.':' Niech świeci. Niech ktoś pilnuje nieba, skoro ja już nie mogę.'),
  o:[{t:'Przyjmij podziękowania',fx:()=>{const t=reward(80+S.stage*6,S.fl.syg==='zgas'?2:1);rep('lud',4);qEnd('sygnal','Odkryliście mechanizm Asterionu na Strażnicy i dziennik ostatniego strażnika. Dawna katastrofa nie była zwykłą wojną. '+t);return {txt:'Jarema wciska wam w dłoń stary róg sygnałowy i kilka monet. '+t}}}]}
};
